DESIGN_CONFETTI = [(255, 214, 102), (52, 211, 153), (96, 165, 250), (248, 113, 113), (196, 160, 255), (255, 255, 255),
                   (255, 150, 60)]
DESIGN_GIF_MAX = 1_500_000


def _design_ease_back(t: float) -> float:
    """0 to 1 with a little overshoot (the pop-in)."""
    t = max(0.0, min(1.0, t))
    k = 1.9
    return 1 + (k + 1) * (t - 1) ** 3 + k * (t - 1) ** 2


def _design_bounce(t: float) -> float:
    """0 to 1 like a ball dropped onto the floor."""
    t = max(0.0, min(1.0, t))
    n, dd = 7.5625, 2.75
    if t < 1 / dd:
        return n * t * t
    if t < 2 / dd:
        t -= 1.5 / dd
        return n * t * t + 0.75
    if t < 2.5 / dd:
        t -= 2.25 / dd
        return n * t * t + 0.9375
    t -= 2.625 / dd
    return n * t * t + 0.984375


def _design_gold_text(text: str, size: int):
    """Gold-gradient lettering with a dark drop shadow, as a tight RGBA image."""
    from PIL import Image, ImageDraw
    f = art_font(size, True)
    w, h = _tw(ImageDraw.Draw(Image.new("L", (1, 1))), text, f) + size // 2, int(size * 1.35)
    out = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    mask = _brand_mask((w, h), lambda d: d.text((size // 4, size // 12), text, font=f, fill=255))
    _brand_paint(out, mask, (20, 8, 0), alpha=200, blur=size / 14, offset=(0, size / 16))
    _brand_paint(out, mask, _brand_lin((w, h), [(255, 250, 225), (255, 214, 102), (210, 140, 20)], 90))
    return out


def render_cash_gif(c: dict) -> io.BytesIO:
    """A 2-second looping GIF for a big cash: the hype mascot drops in, confetti falls, CASHED pops and the
    winnings count up. c: name, avatar (bytes), net, cost, returned, sport, accent. Under 1.5 MB."""
    from PIL import Image, ImageChops, ImageDraw, ImageFilter
    W, H, N = 600, 336, 22
    net = float(c.get("net") or 0)
    rnd = _random.Random(int(abs(net) * 100) + len(c.get("name") or ""))
    sport = design_sport_key(c.get("sport"))
    accent = tuple(c.get("accent") or BRAND_DEFAULT_ACCENT)
    mx, my = 140, 178
    stage = ImageChops.add(sport_backdrop(sport, (W, H), (255, 214, 102)),
                           _brand_radial((W, H), mx, my, W * 0.55, [(120, 80, 26), (40, 24, 8), (0, 0, 0)])).convert("RGBA")
    rays = Image.new("L", (W, H), 0)           # a still sunburst: moving rays would redraw every pixel every frame
    rd = ImageDraw.Draw(rays)
    for k in range(16):
        a0 = math.radians(k * 22.5 + 4)
        rd.polygon([(mx, my), (mx + math.cos(a0) * W * 1.4, my + math.sin(a0) * W * 1.4),
                    (mx + math.cos(a0 + 0.17) * W * 1.4, my + math.sin(a0 + 0.17) * W * 1.4)], fill=255)
    _brand_paint(stage, rays, (255, 214, 102), alpha=24)
    edge = _brand_mask((W, H), lambda d: d.rectangle((3, 3, W - 4, H - 4), outline=255, width=3))
    _brand_paint(stage, edge, (255, 206, 90), alpha=150, blur=4)
    brand_sign(stage, W - 14, H - 26, "PIMP-BOT", 12, variant="hype", accent=accent)
    mascot = brand_logo(156, "hype", accent)
    shadow = _brand_mask((176, 50), lambda d: d.ellipse((28, 16, 148, 34), fill=255)).filter(ImageFilter.GaussianBlur(6))
    cashed = _design_gold_text("CASHED", 52)
    name = clip(str(c.get("name") or "Somebody"), 22)
    line = f"{money_short(c.get('cost') or 0)} → {money_short(c.get('returned') or 0)}"
    mult = (float(c.get("returned") or 0) / float(c["cost"])) if c.get("cost") else 0
    if mult >= 2:
        line += f"  ·  {mult:.0f}x"
    av = _avatar(c.get("avatar"), 42, name, -1)
    glyph = design_glyph(sport, 26)
    parts = [[rnd.random() * W, -rnd.random() * H * 1.2, 2.5 + rnd.random() * 4.5, rnd.uniform(-1.2, 1.2),
              rnd.random() * 6.28, rnd.uniform(-0.5, 0.5), rnd.choice(DESIGN_CONFETTI), 3 + rnd.random() * 4]
             for _ in range(72)]
    sparks = [(rnd.uniform(270, W - 30), rnd.uniform(30, 120), rnd.uniform(5, 10), rnd.randrange(N)) for _ in range(5)]
    frames = []
    tx = 282
    for fi in range(N):
        fr = stage.copy()
        drop = _design_bounce(fi / 8)                       # the mascot drops in and bounces, then bobs
        y = int(my - 78 - (1 - drop) * 240 + (math.sin(fi * 0.7) * 4 if fi > 8 else 0))
        fr.paste((0, 0, 0, 255), (mx - 88, my + 52), shadow.point(lambda v, k=drop: int(v * 0.6 * k)))
        fr.alpha_composite(mascot, (mx - 78, y))
        d = ImageDraw.Draw(fr)
        if fi >= 3:
            sc = _design_ease_back((fi - 3) / 6)
            if sc > 0.05:
                cw, ch = max(1, int(cashed.width * sc)), max(1, int(cashed.height * sc))
                fr.alpha_composite(cashed.resize((cw, ch), Image.BILINEAR),
                                   (int(tx + cashed.width / 2 - cw / 2), int(66 + cashed.height / 2 - ch / 2)))
        if fi >= 6:
            shown = net * min(1.0, 1 - (1 - (fi - 5) / 8) ** 3)
            _, f = fit_text(d, signed_short(net), W - tx - 20, 62, True, 28)      # one size for the whole count
            t = signed_short(round(shown) if fi < 13 else net)
            box = Image.new("RGBA", (W - tx + 20, 104), (0, 0, 0, 0))
            _brand_paint(box, _brand_mask(box.size, lambda dd: dd.text((26, 20), t, font=f, fill=255)), ART_GREEN,
                         alpha=150, blur=10)
            fr.alpha_composite(box, (tx - 20, 114))
            d = ImageDraw.Draw(fr)
            d.text((tx + 6, 134), t, font=f, fill=(230, 255, 240))
        if fi >= 10:
            a = min(255, (fi - 9) * 70)
            fade = av if a >= 255 else Image.blend(Image.new("RGBA", av.size, (0, 0, 0, 0)), av, a / 255)
            fr.alpha_composite(fade, (tx + 8, 230))
            t, f = fit_text(d, name, W - tx - 110, 22, True, 14)
            d.text((tx + 60, 229), t, font=f, fill=(255, 255, 255, a))
            t, f = fit_text(d, line, W - tx - 80, 17, True, 12)
            d.text((tx + 60, 256), t, font=f, fill=(206, 206, 224, a))
            if sport != "stadium" and a >= 255:
                fr.alpha_composite(glyph, (W - 46, 229))
        for sx, sy, sr, phase in sparks:                    # twinkles around the money
            k = (fi - phase) % N
            if k < 4:
                rr = sr * (1 - abs(k - 1.5) / 2)
                d.polygon(_brand_sparkle(sx, sy, rr, 16), fill=(255, 246, 214))
        for p in parts:
            x = p[0] + math.sin(fi * 0.5 + p[4]) * 6
            yy = p[1] + p[2] * fi * 3.2 + (60 if fi > 0 else 0)
            ang = p[4] + p[5] * fi * 3
            sz = p[7]
            if -10 < yy < H + 10:
                ca, sa = math.cos(ang), math.sin(ang)
                d.polygon([(x + ca * dx - sa * dy, yy + sa * dx + ca * dy) for dx, dy in
                           ((-sz, -sz * 0.45), (sz, -sz * 0.45), (sz, sz * 0.45), (-sz, sz * 0.45))], fill=p[6] + (255,))
        frames.append(fr.convert("RGB"))
    # one shared palette from the busiest frames keeps colours steady and the file small
    strip = Image.new("RGB", (W, H * 3))
    for k, fi in enumerate((7, 13, N - 1)):
        strip.paste(frames[fi], (0, H * k))
    out = None
    for colours in (168, 112, 64):
        pal = strip.quantize(colors=colours, method=Image.Quantize.MEDIANCUT)
        q = [fr.quantize(palette=pal, dither=Image.Dither.NONE) for fr in frames]
        out = io.BytesIO()
        q[0].save(out, "GIF", save_all=True, append_images=q[1:], duration=[75] * (N - 1) + [700], loop=0,
                  disposal=1, optimize=False)
        if out.tell() <= DESIGN_GIF_MAX:
            break
    out.seek(0)
    return out


async def design_bigwin_file(client, p) -> Optional[discord.File]:
    """The celebration GIF for a big cash (server toggle `cashgifs`), or the static receipt if the GIF can't be
    drawn, or None when the toggle is off. Everything from the database is read before the render thread."""
    if not server_on(p["guild_id"], "cashgifs"):
        return None
    user = await known_user(client, p["bettor_id"]) if p["bettor_id"] else None
    av = await avatar_bytes(user) if user is not None else None
    data = {"name": call_name(p["guild_id"], p["bettor_key"], p["bettor_name"]), "avatar": av, "net": pick_net(p),
            "cost": p["cost"], "returned": p["returned"] or 0, "sport": p["sport"],
            "accent": brand_for(p["guild_id"])["accent"]}
    try:
        gif = await asyncio.to_thread(locked_render, render_cash_gif, data)
        if gif.getbuffer().nbytes <= 7 * 1024 * 1024:
            return discord.File(gif, filename="cashed.gif")
    except Exception:
        log.warning("Cash GIF failed for pick %s; sending the receipt", p["id"], exc_info=True)
    try:
        return await receipt_file(client, p, db_entries(p))
    except Exception:
        log.warning("Receipt fallback failed for pick %s", p["id"], exc_info=True)
        return None


# ==========================================================================
# r30: the dashboard catches up with the bot. A Live tab with the same picture as /live (team logos, score, clock,
# game progress, each leg's pace bar and status), game pages with the /gamecard picture, the news feed, and a bot
# health panel. Same rules as the rest of the dashboard: cookie login, CSP, rate limits, hidden slips never shown.
# ==========================================================================

DASH30_TTL = 15.0                 # seconds the live/news/health JSON is reused between viewers
DASH30_IMG_TTL = 60.0             # rendered pictures (/live, game cards)
DASH30_RENDER_RATE = (40, 60.0)   # pictures one IP may have rendered per window (they cost CPU)
DASH30_LOGO_PX = 160              # logos are re-drawn as small PNGs at most this big
DASH30_ROWS = 30                  # legs per game in the JSON
DASH30_HOSTS = {"generativelanguage.googleapis.com": "Gemini", "api.anthropic.com": "Claude"}
_DASH30_CACHE: dict = {}
_DASH30_LOGO_URLS: dict = {}      # event id -> {"a": url, "h": url}, filled when the live data is built
_DASH30_LOGOS: dict = {}          # logo url -> (expires, png bytes or None)
_DASH30_EID = re.compile(r"[A-Za-z0-9]{1,24}")


def _dash30_cached(key, ttl: float = DASH30_TTL):
    hit = _DASH30_CACHE.get(key)
    return hit[1] if hit and hit[0] > time.monotonic() else None


def _dash30_keep(key, value, ttl: float = DASH30_TTL):
    _DASH30_CACHE[key] = (time.monotonic() + ttl, value)
    if len(_DASH30_CACHE) > 300:
        now = time.monotonic()
        for k, (exp, _) in list(_DASH30_CACHE.items()):
            if exp <= now:
                _DASH30_CACHE.pop(k, None)
    return value


def _dash30_hex(c: tuple) -> str:
    return "#%02x%02x%02x" % tuple(int(x) for x in c[:3])


def _dash30_num(x):
    """A stat as a plain JSON number (no NaN/inf), or None."""
    try:
        f = float(x)
    except (TypeError, ValueError):
        return None
    return round(f, 2) if math.isfinite(f) else None


# ---- the live data (public slips only, same source as /live and /gamecard) -----------------------------------

def dash30_row(r: dict) -> dict:
    """One leg for the web: who, the leg, the number, the line, where it's headed, and its state. No money."""
    n = r.get("num") or {}
    return {"pid": r["pid"], "n": r.get("n"), "who": clip(r.get("who") or "", 40), "text": clip(r.get("text") or "", 120),
            "label": clip(leg_label(r.get("text") or ""), 40), "state": r.get("state") or "waiting",
            "chip": LV_LABEL.get(r.get("state") or "", "SOON"), "value": _dash30_num(n.get("value")),
            "line": _dash30_num(n.get("line")), "side": n.get("side") if n.get("side") in ("over", "under") else None,
            "pace": _dash30_num(r.get("pace")), "slip_open": bool(r.get("slip_open"))}


def dash30_game(g: dict) -> dict:
    """A game the group is on, for the web: teams (logo, colour, score), status, how much is played, and its legs."""
    ev = g["ev"]
    final = bool(ev.get("final") or ev.get("state") == "post")
    state = "post" if final else (ev.get("state") if ev.get("state") in ("pre", "in") else "pre")
    el = lv2_elapsed(ev, g["path"]) if state != "pre" else None
    rows = lv2_game_rows(g)
    for r in rows:
        n = r.get("num")
        r["pace"] = (lv2_pace(n["value"], n["line"], el, r["text"])
                     if n and state == "in" and r["state"] not in ("cleared", "dead") else None)
    away, home = lv_sides(ev)
    ac = lv_team_colour(away)
    hc = lv_team_colour(home, avoid=ac)
    eid = clip(str(g["id"]), 24)
    urls = {}

    def side(t: dict, colour: tuple, key: str) -> dict:
        if t.get("logo"):
            urls[key] = t["logo"]
        return {"abbr": clip(lv_abbr(t), 4), "name": clip(t.get("short") or t.get("name") or lv_abbr(t), 24),
                "score": None if state == "pre" else _dash30_num(t.get("score")), "color": _dash30_hex(colour),
                "logo": f"/img/logo/{eid}/{key}.png" if t.get("logo") and _DASH30_EID.fullmatch(eid) else None}
    out_rows = [dash30_row(r) for r in rows[:DASH30_ROWS]]
    when = event_time(ev)
    out = {"id": eid, "league": LEAGUE_NAMES.get(g["path"] or "", ""), "state": state,
           "status": clip(lv_status_text(dict(ev, final=final)), 30), "elapsed": _dash30_num(el),
           "start": when.isoformat() if when else "", "away": side(away, ac, "a"), "home": side(home, hc, "h"),
           "rows": out_rows, "more": max(0, len(rows) - DASH30_ROWS), "people": len({r["who"] for r in out_rows}),
           "counts": lv_counts(rows)}
    if urls:
        _DASH30_LOGO_URLS[eid] = urls
        if len(_DASH30_LOGO_URLS) > 500:
            for k in list(_DASH30_LOGO_URLS)[:250]:
                _DASH30_LOGO_URLS.pop(k, None)
    return out


async def dash30_games(gid: int, now: datetime) -> list[dict]:
    """The games the group's public slips ride on (live first, then later today, then tonight's finals)."""
    snap = await lv_snapshot(gid, now)
    return lv2_card_games(gid, snap, now, 0)


async def dash30_live(gid: int) -> dict:
    """The Live tab: games in play with every leg, the ones later today, and tonight's finals."""
    hit = _dash30_cached(("live", gid))
    if hit is not None:
        return hit
    now = datetime.now(timezone.utc)
    games = [dash30_game(g) for g in await dash30_games(gid, now)]
    by = {"in": [], "pre": [], "post": []}
    for g in games:
        by[g["state"]].append(g)
    for g in by["pre"] + by["post"]:
        g["rows"] = g["rows"][:12]
    return _dash30_keep(("live", gid), {"games": by["in"][:12], "later": by["pre"][:12], "finals": by["post"][:12],
                                        "updated": datetime.now(TZ).strftime("%-I:%M %p")})


async def dash30_one_game(gid: int, eid: str):
    """(game JSON, the game as lv2_card_games has it) or (None, None)."""
    now = datetime.now(timezone.utc)
    g = next((x for x in await dash30_games(gid, now) if str(x["id"]) == eid), None)
    return (dash30_game(g), g) if g is not None else (None, None)


# ---- the news feed (what the ask channel has posted), newest first --------------------------------------------

def _dash30_players(gid: int, hidden: bool) -> dict[str, dict]:
    """{player key: {name, slips: [(who, pick id)]}} for the recent slips that are still secret (hidden=True: open, or settled but
    not revealed yet), or for the open public ones."""
    since = iso(datetime.now(timezone.utc) - timedelta(days=AUTOPILOT_DAYS))
    cond = ("hidden = 1 AND (status = 'open' OR revealed_at IS NULL)" if hidden
            else "status = 'open' AND (hidden IS NULL OR hidden = 0)")
    out: dict = {}
    for p in db().execute(f"SELECT id, bettor_name, description FROM picks WHERE guild_id = ? AND created_at >= ? "
                          f"AND {cond} ORDER BY id DESC LIMIT 80", (gid, since)).fetchall():
        legs = get_legs(p["id"])
        for text in ([x["text"] for x in legs] or [p["description"]]):
            leg = prop_of(text or "")
            for part in ((leg or {}).get("combo") or ([leg] if leg else [])):
                w = out.setdefault(part["player"], {"name": part.get("display") or part["player"].title(), "slips": []})
                if (p["bettor_name"], p["id"]) not in w["slips"]:
                    w["slips"].append((p["bettor_name"], p["id"]))
    return out


def _dash30_chip(status: Optional[str]) -> str:
    s = (status or "").lower()
    for k in ("out", "doubtful", "questionable", "day-to-day", "suspension", "probable", "active"):
        if s.startswith(k):
            return k
    return "other"


def dash30_news(gid: int) -> list[dict]:
    """The news feed's injury and reboot items, newest first. A player who's only on hidden slips never shows,
    and reboots on hidden slips stay out (like the feed itself)."""
    hit = _dash30_cached(("news", gid))
    if hit is not None:
        return hit
    c = news_db()
    public = _dash30_players(gid, hidden=False)
    secret = _dash30_players(gid, hidden=True)
    out = []
    for r in c.execute("SELECT key, status, detail, posted_at FROM news_seen WHERE guild_id = ? AND posted_at IS NOT NULL "
                       "ORDER BY posted_at DESC LIMIT 80", (gid,)).fetchall():
        key = r["key"] or ""
        if key.startswith("inj:"):
            player = key[4:]
            if player in secret and player not in public:
                continue
            st = r["status"]
            w = public.get(player) or {"name": player.title(), "slips": []}
            out.append({"kind": "injury" if st else "off", "player": clip(w["name"], 60),
                        "status": clip(st or "Off the report", 30), "chip": _dash30_chip(st) if st else "off",
                        "detail": clip(r["detail"] or "", 240) if st else "",
                        "slips": [{"id": pid, "who": clip(who, 30)} for who, pid in w["slips"][:4]],
                        "when": r["posted_at"]})
        elif key.startswith("dnp:"):
            m = re.fullmatch(r"dnp:(\d{1,10}):(\d{1,3})", key)
            p = get_pick(gid, int(m.group(1))) if m else None
            if p is None or p["hidden"]:
                continue
            leg = db().execute("SELECT text, note FROM legs WHERE pick_id = ? AND idx = ?",
                               (p["id"], int(m.group(2)))).fetchone()
            prop = prop_of(leg["text"]) if leg else None
            name = (prop or {}).get("display") or (leg_label(leg["text"]) if leg else "A leg")
            out.append({"kind": "reboot", "player": clip(name, 60),
                        "status": "Reboot", "chip": "reboot",
                        "detail": clip((leg["note"] if leg and leg["note"] else "Didn't play") + ". The leg is voided.", 240),
                        "slips": [{"id": p["id"], "who": clip(p["bettor_name"], 30)}], "when": r["posted_at"]})
        if len(out) >= 40:
            break
    return _dash30_keep(("news", gid), out)


# ---- bot health: no keys, no error text, no paths -------------------------------------------------------------

def _dash30_ago(ts: Optional[float], now: float) -> Optional[str]:
    return None if not ts else _track_ago(ts, now)


def dash30_health() -> dict:
    """Data feeds, today's slip reads and questions, the scheduler, the version. Safe to show anyone signed in."""
    now = time.time()
    feeds = [{"name": "Dashboard", "state": "ok", "ok": 1, "fail": 0, "last_ok": "just now", "code": None}]
    hosts = list(HEALTH_NAMES) + sorted(h for h in DATA_HEALTH if h not in HEALTH_NAMES)
    for host in hosts[:20]:
        h = DATA_HEALTH.get(host)
        name = clip(HEALTH_NAMES.get(host) or DASH30_HOSTS.get(host) or host, 40)
        if not h:
            feeds.append({"name": name, "state": "idle", "ok": 0, "fail": 0, "last_ok": None, "code": None})
            continue
        state = "down" if h.get("streak", 0) >= 3 else ("shaky" if h.get("streak", 0) else "ok")
        code = h.get("status")
        feeds.append({"name": name, "state": state, "ok": int(h.get("ok") or 0), "fail": int(h.get("fail") or 0),
                      "last_ok": _dash30_ago(h.get("last_ok"), now), "code": code if isinstance(code, int) else None})
    try:
        counts = json.loads(get_setting(0, f"slipreads:{datetime.now(TZ).date().isoformat()}") or "{}")
    except ValueError:
        counts = {}
    counts = counts if isinstance(counts, dict) else {}
    num = lambda k: int(counts.get(k) or 0) if str(counts.get(k) or 0).isdigit() else 0
    reads = [{"name": n, "n": num(k)} for k, n in (("scan", "Free scan"), ("scan_confirm", "Free scan, fixed by hand"),
                                                    ("gemini", "Gemini (free)"), ("claude", "Claude"))]
    questions = [{"name": n, "n": num(k)} for k, n in (("ask_gemini", "Gemini (free)"), ("ask_claude", "Claude"))]
    on = [{"scan": "Free scan", "gemini": "Gemini", "claude": "Claude"}[r] for r in SLIP_READERS
          if (r == "scan" and TESSERACT) or (r == "gemini" and GEMINI_API_KEY) or (r == "claude" and ai_enabled())]
    last = _last_cycle.get("at")
    try:
        last_ts = datetime.fromisoformat(last).timestamp() if last else None
    except ValueError:
        last_ts = None
    up = datetime.now(timezone.utc) - STARTED_AT
    failing = [{"name": clip(k, 40), "fails": int(v.get("fails") or 0)} for k, v in JOB_HEALTH.items() if v.get("fails")]
    try:
        claude_n = int(claude_calls_today())
    except Exception:
        claude_n = 0
    last_job = ""
    best_ok = ""
    for jname, jh in JOB_HEALTH.items():
        ok_at = jh.get("ok_at") or ""
        if ok_at >= best_ok:
            best_ok, last_job = ok_at, jname
    return {"version": BOT_VERSION, "uptime": f"{up.days}d {up.seconds // 3600}h {(up.seconds // 60) % 60}m",
            "cycle": {"ago": _dash30_ago(last_ts, now), "ok": bool(last_ts and now - last_ts < 600)},
            "last_job": last_job or "not yet",
            "jobs": {"total": len(JOB_HEALTH), "failing": failing[:8]}, "feeds": feeds, "reads": reads,
            "questions": questions, "readers_on": on, "claude_today": claude_n}


# ---- pictures --------------------------------------------------------------------------------------------------

def _dash30_logo_png(raw: bytes) -> Optional[bytes]:
    """Re-draw a logo as a small PNG (so whatever ESPN sent, the browser only ever gets a clean PNG)."""
    from PIL import Image
    try:
        img = Image.open(io.BytesIO(raw))
        sec_check_image(img)
        img = img.convert("RGBA")
        img.thumbnail((DASH30_LOGO_PX, DASH30_LOGO_PX), Image.LANCZOS)
        return _png(img).getvalue()
    except Exception:
        return None


async def dash30_logo_bytes(eid: str, side: str) -> Optional[bytes]:
    """A team's logo for a game the group is on, through team_logo_bytes (ESPN's image hosts only)."""
    url = (_DASH30_LOGO_URLS.get(eid) or {}).get(side)
    if not url:
        _, ev = lv_cached_event(eid)
        if ev:
            away, home = lv_sides(ev)
            url = (away if side == "a" else home).get("logo")
    if not url:
        return None
    hit = _DASH30_LOGOS.get(url)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    raw = await team_logo_bytes(url)
    png = await asyncio.to_thread(_dash30_logo_png, raw) if raw else None
    _DASH30_LOGOS[url] = (time.monotonic() + (86400 if png else 900), png)
    if len(_DASH30_LOGOS) > 300:
        for k in list(_DASH30_LOGOS)[:150]:
            _DASH30_LOGOS.pop(k, None)
    return png


async def dash30_live_png(gid: int) -> Optional[bytes]:
    """The /live picture for everyone's public slips (a still PNG), or None when nothing is in play."""
    hit = _dash30_cached(("livepng", gid))
    if hit is not None:
        return hit or None
    now = datetime.now(timezone.utc)
    snap = await lv_snapshot(gid, now)
    data = await lv2_board_data(bot, gid, "a", 0, False, now, snap)
    out = (await asyncio.to_thread(locked_render, render_live_board, data)).getvalue() if data else b""
    return _dash30_keep(("livepng", gid), out, DASH30_IMG_TTL) or None


async def dash30_game_png(gid: int, eid: str) -> Optional[bytes]:
    """The game card (as /gamecard draws it) for one game the group's public slips ride on."""
    hit = _dash30_cached(("gamepng", gid, eid))
    if hit is not None:
        return hit or None
    now = datetime.now(timezone.utc)
    _, g = await dash30_one_game(gid, eid)
    out = b""
    if g is not None:
        final = bool(g["ev"].get("final") or g["ev"].get("state") == "post")
        data = await lv_card_data(bot, gid, lv_trim_event(g["ev"]), g["path"], lv2_game_rows(g), final, now)
        out = (await asyncio.to_thread(locked_render, render_game_card, data)).getvalue()
    return _dash30_keep(("gamepng", gid, eid), out, DASH30_IMG_TTL) or None


# ---- the handlers (every one goes through dash_guard via dash_app, and dash_gate for the login) ----------------

def _dash30_png(web, png: Optional[bytes], age: int = 60):
    if not png:
        return web.Response(text="nothing to show", status=404, content_type="text/plain")
    return web.Response(body=png, content_type="image/png", headers={"Cache-Control": f"private, max-age={age}"})


def _dash30_render_ok(request) -> bool:
    return dash_rate(dash_client_ip(request), "render", *DASH30_RENDER_RATE)


async def dash30_api_live(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    return web.json_response(await dash30_live(prm["guild"]))


async def dash30_api_game(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    eid = request.match_info.get("eid", "")
    d = (await dash30_one_game(prm["guild"], eid))[0] if _DASH30_EID.fullmatch(eid) else None
    return web.json_response(d) if d else dash_error(web, request, 404)


def news_cached_team(name: str) -> str:
    """Team from an injury report already loaded in this process. No network."""
    key = norm_name(name or "")
    if len(key) < 3:
        return ""
    for cached in _injury_cache.values():
        report = cached[1] if isinstance(cached, tuple) and len(cached) > 1 else None
        if not isinstance(report, dict):
            continue
        best, team, ambiguous = 0, "", False
        for k, v in report.items():
            if not isinstance(v, dict):
                continue
            sc = name_score(key, str(k))
            if sc > best:
                best, team, ambiguous = sc, str(v.get("team") or ""), bool(v.get("ambiguous"))
        if best >= 2 and team and not ambiguous:
            return clip(team, 40)
    return ""


async def dash30_api_news(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    gid = prm["guild"]
    items = [dict(x) for x in dash30_news(gid)]
    for it in items:
        team = news_cached_team(it.get("player") or "")
        if team and not it.get("team"):
            it["team"] = team
    return web.json_response({"items": items, "on": bool(ask_channel_id(gid)) and server_on(gid, "newsfeed")})


async def dash30_api_newsface(request):
    """One player's photo and team for the news row. One match only, so two players with one name stay blank."""
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    if not dash_rate(dash_client_ip(request), "newsface", 40, 60):
        return dash_error(web, request, 429)
    q = clip(str(request.query.get("q") or "").strip(), 40)
    if len(q) < 3:
        return web.json_response({})
    try:
        found = await resolve_player(q, list(PROP_PATHS))
    except Exception:
        found = []
    if len(found) != 1 or name_score(norm_name(q), found[0].get("norm") or "") < 2:
        return web.json_response({})
    f = found[0]
    league = design_head_league(f.get("path")) or ""
    aid = str(f.get("id") or "")
    out = {"team": clip(f.get("team") or "", 40), "abbr": clip(f.get("team_abbr") or "", 8)}
    if league and aid.isdigit():
        out["slug"] = league
        out["aid"] = aid
    return web.json_response(out)


async def dash30_api_health(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    return web.json_response(dash30_health())


async def dash30_live_img(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    if not _dash30_render_ok(request):
        return dash_error(web, request, 429)
    try:
        png = await dash30_live_png(prm["guild"])
    except Exception:
        log.exception("Dashboard live picture failed")
        png = None
    return _dash30_png(web, png)


async def dash30_game_img(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    eid = request.match_info.get("eid", "")
    if not _DASH30_EID.fullmatch(eid):
        return dash_error(web, request, 404)
    if not _dash30_render_ok(request):
        return dash_error(web, request, 429)
    try:
        png = await dash30_game_png(prm["guild"], eid)
    except Exception:
        log.exception("Dashboard game card failed")
        png = None
    return _dash30_png(web, png)


async def dash30_logo(request):
    from aiohttp import web
    prm, err = dash_gate(web, request)
    if err is not None:
        return err
    eid, side = request.match_info.get("eid", ""), request.match_info.get("side", "")
    if not _DASH30_EID.fullmatch(eid) or side not in ("a", "h"):
        return dash_error(web, request, 404)
    return _dash30_png(web, await dash30_logo_bytes(eid, side), 86400)


def dash30_routes(web) -> list:
    """The r30 routes; dash_app puts them ahead of the generic /img/{kind}.png ones."""
    return [web.get("/api/live.json", dash30_api_live), web.get(r"/api/game/{eid:[A-Za-z0-9]+}.json", dash30_api_game),
            web.get("/api/news.json", dash30_api_news), web.get("/api/newsface.json", dash30_api_newsface),
            web.get("/api/health.json", dash30_api_health),
            web.get("/img/live.png", dash30_live_img), web.get(r"/img/game/{eid:[A-Za-z0-9]+}.png", dash30_game_img),
            web.get(r"/img/logo/{eid:[A-Za-z0-9]+}/{side:[ah]}.png", dash30_logo)]


def dash30_safe_records(guild_id: int, text: str) -> str:
    """The record book for the web: a hidden slip that hasn't been revealed yet shows as 'Hidden pick', never its
    description (records_embed names the biggest hit and worst beat by description)."""
    for p in db().execute("SELECT * FROM picks WHERE guild_id = ? AND hidden = 1 AND (status = 'open' OR revealed_at IS NULL)",
                          (guild_id,)).fetchall():
        desc = clip(p["description"] or "", 50)
        if desc and dash_secret(p):
            text = text.replace(desc, "Hidden pick")
    return text


# --------------------------------------------------------------------------
# The bot
# --------------------------------------------------------------------------

class PicksBot(discord.Client):
    def __init__(self):
        intents = discord.Intents.default()
        intents.message_content = True  # needed to see screenshots and questions
        if MEMBERS_INTENT:
            intents.members = True       # only for welcome DMs; also switch it on in the developer portal
        super().__init__(intents=intents)
        self.allowed_mentions = SEC_MENTIONS   # nothing the bot sends can ping @everyone/@here/roles unless asked
        self.tree = app_commands.CommandTree(self)
        self.receipt_channels: set[int] = set()
        self.ask_cooldowns: dict[int, float] = {}

    async def setup_hook(self):
        self.receipt_channels = receipt_channel_ids()
        self.add_dynamic_items(SettleButton, LogSlipButton, FollowButton, ChallengeButton, PickemButton,
                               SlipWhoSelect,
                               SweatButton, InjuryOffButton, GPButton, CopyButton, CardSweatButton, CardKalshiButton,
                               PPSettleButton, MarketButton, TakeButton, PotdButton, TriviaButton, GuessButton,
                               ClosestButton, SquaresButton, DraftButton, NoteButton, DisputeButton, FixButton,
                               BoardButton, BootRefreshButton, SlipDraftButton, FixPickButton, TrackerButton)
        if EXTRA_ITEMS:
            self.add_dynamic_items(*EXTRA_ITEMS)
        r14_db()
        r15_db()
        try:
            await start_dashboard()
        except Exception:
            log.exception("Dashboard didn't start")
        if GUILD_ID:
            guild = discord.Object(id=int(GUILD_ID))
            self.tree.copy_global_to(guild=guild)
            await self.tree.sync(guild=guild)  # shows up instantly in that server
        else:
            await self.tree.sync()  # global: can take up to an hour to appear
        self.scheduler_task = asyncio.create_task(self.scheduler())

    async def on_ready(self):
        log.info("Logged in as %s | version %s | update %s | Claude features: %s | receipts channels: %d",
                 self.user, BOT_VERSION, ROADMAP_NOW, "on" if ai_enabled() else "off",
                 len(self.receipt_channels))
        if not getattr(self, "_boot_said", False):
            self._boot_said = True
            try:
                await announce_boot(self)
            except Exception:
                log.exception("Boot announce failed")

    async def on_disconnect(self):
        try:
            set_setting(0, "bot_disconnect_at", now_iso())
        except Exception:
            pass
        crash_note("bot", "Robot disconnected", "Lost the Discord websocket. It will try to reconnect.")
        last = getattr(self, "_disc_ping_at", 0)
        if time.monotonic() - last < 600:
            return
        self._disc_ping_at = time.monotonic()
        try:
            await asyncio.wait_for(
                crash_notify(self, "bot", "Robot disconnected",
                             "Lost the Discord websocket. It will try to reconnect."), 4)
        except Exception:
            pass

    async def on_resumed(self):
        crash_note("ok", "Robot reconnected", "Discord websocket is back.")

    async def close(self):
        try:
            set_setting(0, "bot_stopping", now_iso())
            last_done = ""
            best_ok = ""
            for jname, jh in JOB_HEALTH.items():
                ok_at = jh.get("ok_at") or ""
                if ok_at >= best_ok:
                    best_ok, last_done = ok_at, jname
            done = f" Last job that finished: {last_done}." if last_done else " No background job had finished yet."
            await asyncio.wait_for(
                post_alert(self, f"🛠️ **PIMP-BOT is going down**\nUpdate or restart. Version was {BOT_VERSION}. "
                           f"It should be back in a minute.{done}"), 5)
        except Exception:
            log.info("Couldn't post going-down note")
        await super().close()

    # ---- scheduled posts ---------------------------------------------------

    async def scheduler(self):
        await self.wait_until_ready()
        try:
            n = await refresh_guides(self)
            if n:
                log.info("Refreshed %d posted guide(s) for version %s", n, BOT_VERSION)
        except Exception:
            log.exception("Guide refresh failed")
        while not self.is_closed():
            try:
                await self.run_schedules()
            except Exception as exc:
                log.exception("Scheduled post failed")
                try:
                    await crash_notify(self, "crash", "Scheduler crashed",
                                      f"{type(exc).__name__}: {exc}"[:180])
                except Exception:
                    crash_note("crash", "Scheduler crashed", f"{type(exc).__name__}: {exc}"[:180])
            await asyncio.sleep(120)

    async def run_autograde(self, now: Optional[datetime] = None, limit: int = 3):
        """Grade picks that are still open AUTOGRADE_AFTER_HOURS after being logged."""
        if not AUTOGRADE_AFTER_HOURS:
            return
        now = now or datetime.now(timezone.utc)
        due = (now - timedelta(hours=AUTOGRADE_AFTER_HOURS)).isoformat(timespec="seconds")
        retry = (now - timedelta(hours=12)).isoformat(timespec="seconds")
        rows = db().execute(
            """SELECT * FROM picks WHERE status = 'open' AND created_at <= ?
               AND COALESCE(autograde_tries, 0) < ? AND (autograde_at IS NULL OR autograde_at <= ?)
               AND (NOT EXISTS (SELECT 1 FROM legs l WHERE l.pick_id = picks.id)
                    OR EXISTS (SELECT 1 FROM legs l WHERE l.pick_id = picks.id AND l.status = 'open'))
               ORDER BY created_at LIMIT ?""",
            (due, AUTOGRADE_MAX_TRIES, retry, limit)).fetchall()
        for p in rows:
            count_key = f"autogrades:{now.astimezone(TZ).date().isoformat()}"
            used = int(get_setting(p["guild_id"], count_key) or 0)
            try:
                pick, lines, graded, used_ai = await autograde(
                    p["guild_id"], p["id"], allow_ai=used < AUTOGRADE_DAILY_LIMIT)
            except Exception:
                log.exception("Auto-grading pick %s failed", p["id"])
                continue
            if used_ai:  # only paid lookups count toward the daily limit
                set_setting(p["guild_id"], count_key, str(used + 1))
            final_try = (pick["autograde_tries"] or 0) >= AUTOGRADE_MAX_TRIES
            if not lines or (not graded and not final_try):
                continue  # nothing new to say; try again later
            channel_id = get_setting(p["guild_id"], "recap_channel")
            channel = self.get_channel(int(channel_id)) if channel_id else None
            if channel is not None and not sec_secret(pick):
                mention = f"<@{pick['bettor_id']}> " if pick["bettor_id"] else ""
                for chunk in split_message(mention + grading_message(pick, lines, final_try)):
                    await channel.send(chunk, allowed_mentions=discord.AllowedMentions(
                        everyone=False, roles=False, users=True))

    async def run_lock_grading(self, now: Optional[datetime] = None, limit: int = 3):
        """Grade locks of the week the same way as picks: 48 hours after they're submitted."""
        if not AUTOGRADE_AFTER_HOURS:
            return
        now = now or datetime.now(timezone.utc)
        due = iso(now - timedelta(hours=AUTOGRADE_AFTER_HOURS))
        retry = iso(now - timedelta(hours=12))
        rows = db().execute(
            """SELECT * FROM locks WHERE status = 'open' AND created_at <= ?
               AND COALESCE(autograde_tries, 0) < ? AND (autograde_at IS NULL OR autograde_at <= ?)
               ORDER BY created_at LIMIT ?""", (due, AUTOGRADE_MAX_TRIES, retry, limit)).fetchall()
        for r in rows:
            count_key = f"autogrades:{now.astimezone(TZ).date().isoformat()}"
            used = int(get_setting(r["guild_id"], count_key) or 0)
            tries = (r["autograde_tries"] or 0) + 1
            db().execute("UPDATE locks SET autograde_at = ?, autograde_tries = ? WHERE id = ?",
                         (now_iso(), tries, r["id"]))
            db().commit()
            like = {"id": -r["id"], "created_at": r["created_at"], "platform": "a weekly pick contest",
                    "sport": r["sport"], "description": r["text"], "notes": None}
            try:
                by_n, used_ai = await lookup_items(like, [(1, r["text"])], True,
                                                   used < AUTOGRADE_DAILY_LIMIT, context_legs=[])
            except Exception:
                log.exception("Grading lock %s failed", r["id"])
                continue
            if used_ai:
                set_setting(r["guild_id"], count_key, str(used + 1))
            res = by_n.get(1) or {}
            result = str(res.get("result", "unknown")).lower()
            channel_id = get_setting(r["guild_id"], "recap_channel")
            channel = self.get_channel(int(channel_id)) if channel_id else None
            if result in ("hit", "miss", "push"):
                status = {"hit": "win", "miss": "loss", "push": "push"}[result]
                settle_lock(r["id"], status, clip(str(res.get("why") or ""), 120) or None)
                if channel is not None:
                    await channel.send(
                        f"🔒 Lock graded: <@{r['user_id']}> {LOCK_ICON[status]} {clip(r['text'], 100)}"
                        + (f" · {clip(str(res.get('why')), 100)}" if res.get("why") else "")
                        + f"\n-# Wrong? Fix it with `/lockresult lock_id:{r['id']}`.",
                        allowed_mentions=discord.AllowedMentions(everyone=False, roles=False, users=True))
            elif tries >= AUTOGRADE_MAX_TRIES and channel is not None:
                await channel.send(
                    f"🔒 I couldn't grade <@{r['user_id']}>'s lock: {clip(r['text'], 100)}. "
                    f"Settle it with `/lockresult lock_id:{r['id']}`.",
                    allowed_mentions=discord.AllowedMentions(everyone=False, roles=False, users=True))

    async def check_limits(self, now: Optional[datetime] = None):
        """Private heads-up to anyone past the weekly loss limit they set, once a week."""
        now = now or datetime.now(TZ)
        week = week_id(now)
        for r in db().execute("SELECT guild_id, key, value FROM settings WHERE key LIKE 'limit:%'").fetchall():
            uid = r["key"].split(":", 1)[1]
            if get_setting(r["guild_id"], f"limitwarned:{uid}") == week:
                continue
            net = weekly_net(r["guild_id"], uid, now)
            if net > -float(r["value"]):
                continue
            set_setting(r["guild_id"], f"limitwarned:{uid}", week)
            try:
                user = await self.fetch_user(int(uid))
                await user.send(
                    f"Heads-up: you're {signed(net)} this week (since Monday), past the "
                    f"{money(float(r['value']))} weekly limit you set. Nothing's been blocked; this is just "
                    "the reminder you asked for. Change it with `/limit` in the server.")
            except Exception:
                log.info("Couldn't DM user %s about their limit", uid)

    async def run_live_grading(self, now: Optional[datetime] = None, limit: int = 40):
        """Settle picks and locks from the free scoreboard as soon as their games go final."""
        now = now or datetime.now(timezone.utc)
        recent = iso(now - timedelta(days=LIVE_WINDOW_DAYS))
        recheck = iso(now - timedelta(minutes=LIVE_RECHECK_MINUTES))
        await autopilot(self, now)
        picks = []
        for p in picks:
            db().execute("UPDATE picks SET live_checked_at = ? WHERE id = ?", (iso(now), p["id"]))
            db().commit()
            items, single = open_items(p)
            if not items or not leagues_for(p["sport"]) or not any(parse_simple_leg(t) or parse_prop_leg(t)
                                                                    for _, t in items):
                continue
            try:
                found = await free_grade(p, items)
            except Exception:
                log.exception("Live check failed for pick %s", p["id"])
                continue
            if not found:
                continue
            by_n = {n: {"result": r, "why": w} for n, (r, w) in found.items()}
            lines, _ = apply_results(p["guild_id"], p["id"], [(n, t) for n, t in items if n in by_n], by_n,
                                     single, only_graded=True)
            after = get_pick(p["guild_id"], p["id"])
            flex_hold = (after["status"] == "open" and after["platform"].lower() == "prizepicks"
                         and any(leg["status"] == "miss" for leg in get_legs(after["id"])))
            if after["status"] == "open" and not flex_hold:
                continue  # some legs done, the rest still going: say nothing yet
            channel = await recap_channel_for(self, after["guild_id"])
            if channel is not None:
                mention = f"<@{after['bettor_id']}> " if after["bettor_id"] else ""
                msg = grading_message(after, lines, False).replace("🤖 Looked up results for", "⚡ Final:", 1)
                for chunk in split_message(mention + msg):
                    await channel.send(chunk, allowed_mentions=discord.AllowedMentions(
                        everyone=False, roles=False, users=True))
        locks = db().execute(
            """SELECT * FROM locks WHERE status = 'open' AND created_at >= ?
               AND (live_checked_at IS NULL OR live_checked_at <= ?) LIMIT ?""", (recent, recheck, limit)).fetchall()
        for lk in locks:
            db().execute("UPDATE locks SET live_checked_at = ? WHERE id = ?", (iso(now), lk["id"]))
            db().commit()
            if not leagues_for(lk["sport"]) or not parse_simple_leg(lk["text"]):
                continue
            like = {"id": -lk["id"], "created_at": lk["created_at"], "sport": lk["sport"], "description": lk["text"]}
            try:
                found = await free_grade(like, [(1, lk["text"])], context_legs=[])
            except Exception:
                log.exception("Live check failed for lock %s", lk["id"])
                continue
            if 1 in found:
                result, why = found[1]
                status = {"hit": "win", "miss": "loss", "push": "push"}[result]
                settle_lock(lk["id"], status, why)
                await post_lock_result(self, lk, status, why)

    async def run_game_pings(self, now: Optional[datetime] = None):
        """DM people who turned on /pings before their games start and at halftime (one DM per game)."""
        now = now or datetime.now(timezone.utc)
        users = [(r["guild_id"], int(r["key"].split(":", 1)[1]))
                 for r in db().execute("SELECT guild_id, key FROM settings WHERE key LIKE 'pings:%' AND value = 'on'")]
        recent = iso(now - timedelta(days=LIVE_WINDOW_DAYS))
        for guild_id, uid in users:
            picks = db().execute("SELECT * FROM picks WHERE guild_id = ? AND bettor_id = ? AND status = 'open' "
                                 "AND created_at >= ? ORDER BY id", (guild_id, uid, recent)).fetchall()
            due: dict[tuple[str, str], dict] = {}  # (event id, kind) -> {"ev", "picks"}
            for p in picks:
                try:
                    games = await games_for_pick(p)
                except Exception:
                    log.exception("Ping lookup failed for pick %s", p["id"])
                    continue
                for ev in games:
                    when = event_time(ev)
                    if when and ev["state"] == "pre" and timedelta(0) < when - now <= timedelta(minutes=PING_MINUTES):
                        kind = "start"
                    elif ev.get("status_name") == "STATUS_HALFTIME" and all(t["score"] is not None for t in ev["teams"]):
                        kind = "half"
                    else:
                        continue
                    if db().execute("SELECT 1 FROM pings WHERE pick_id = ? AND event_id = ? AND kind = ?",
                                    (p["id"], ev["id"], kind)).fetchone():
                        continue
                    due.setdefault((ev["id"], kind), {"ev": ev, "picks": []})["picks"].append(p)
            for (event_id, kind), item in due.items():
                ev, ps = item["ev"], item["picks"]
                away = next(t for t in ev["teams"] if not t["home"])
                home = next(t for t in ev["teams"] if t["home"])
                if kind == "start":
                    mins = max(1, round((event_time(ev) - now).total_seconds() / 60))
                    head = f"⏰ {away['short']} @ {home['short']} starts in {mins} min."
                else:
                    head = f"🏈 Halftime: {away['short']} {away['score']:g}, {home['short']} {home['score']:g}."
                riding = "\n".join(f"• Pick `#{p['id']}`: {clip(p['description'], 80)}" for p in ps[:10])
                db().executemany("INSERT OR IGNORE INTO pings (pick_id, event_id, kind) VALUES (?,?,?)",
                                 [(p["id"], event_id, kind) for p in ps])
                db().commit()
                try:
                    if is_quiet(guild_id, uid):
                        raise QuietHours()
                    user = await self.fetch_user(uid)
                    await user.send(f"{head} Riding on it:\n{riding}")
                except Exception:
                    log.info("Couldn't DM user %s a game ping", uid)

    async def post_today(self, now: datetime):
        for r in db().execute("SELECT guild_id, value FROM settings WHERE key = 'today_channel'").fetchall():
            today = now.date().isoformat()
            if now.hour < TODAY_HOUR or get_setting(r["guild_id"], "last_today") == today:
                continue
            set_setting(r["guild_id"], "last_today", today)
            channel = self.get_channel(int(r["value"]))
            if channel is None:
                continue
            embeds = [e for e in [await today_embed(p, now) for p in group_leagues(r["guild_id"])[:10]] if e]
            if embeds:
                await channel.send("📅 Today's games", embeds=embeds)

    async def job_alert(self, alert: Optional[str]) -> None:
        if not alert:
            return
        kind = "bot" if alert.startswith("⚠️") or "failed" in alert.lower() else "ok"
        title = "Robot job failed" if kind == "bot" else "Robot recovered"
        await crash_notify(self, kind, title, alert)

    async def run_schedules(self, now: Optional[datetime] = None):
        now = now or datetime.now(TZ)
        _last_cycle["at"] = now_iso()
        try:
            set_setting(0, "bot_heartbeat", now_iso())
        except Exception:
            pass
        for job in (self.run_live_grading, lambda n: grade_pickem_games(self, n), lambda n: post_hall_of_fame(self),
                    self.run_game_pings, lambda n: self.post_today(n.astimezone(TZ)),
                    lambda n: grade_survivor(self, n), lambda n: send_reminders(self, n),
                    lambda n: post_backups(self, n), lambda n: update_sweats(self, n),
                    lambda n: run_injury_alerts(self, n), lambda n: grade_kalshi(self, n),
                    lambda n: grade_group_parlays(self, n), lambda n: post_weekly_group_parlay(self, n),
                    lambda n: offer_pp_settlements(self, n), lambda n: one_leg_alerts(self, n),
                    lambda n: react_to_slips(self, n), lambda n: award_coins(self, n), lambda n: close_markets(self, n),
                    lambda n: takes_due(self, n), lambda n: post_potd(self, n), lambda n: grade_potd(self, n),
                    lambda n: reveal_hidden(self, n), lambda n: close_trivia(self, n), lambda n: grade_closest(self, n),
                    lambda n: run_squares(self, n), lambda n: finish_drafts(self, n),
                    lambda n: grade_player_survivor(self, n), lambda n: futures_due(self, n),
                    lambda n: announce_levels(self, n), lambda n: expire_color_roles(self, n),
                    lambda n: post_rivals(self, n), lambda n: bounty_check(self, n), lambda n: on_this_day(self, n),
                    lambda n: big_moments(self, n), lambda n: favorite_team_alerts(self, n),
                    lambda n: run_game_threads(self, n), lambda n: post_announcements(self, n),
                    lambda n: lineup_checks(self, n), lambda n: deadline_nudges(self, n),
                    lambda n: cheer_settled(self, n), lambda n: personal_milestones(self, n),
                    lambda n: update_receipts(self, n), lambda n: update_boards(self, n),
                    lambda n: voice_idle(self, n), lambda n: leg_watch(self, n),
                    lambda n: grade_ghosts(self, n), lambda n: nightly_cleanup(self, n),
                    lambda n: send_digests(self, n), lambda n: game_previews(self, n), lambda n: check_quests(self, n),
                    *[_named_job(name, fn, self) for name, fn in EXTRA_JOBS]):
            name = job_name(job)
            if job_recently_clean(name):
                continue
            try:
                await asyncio.wait_for(job(now.astimezone(timezone.utc)), timeout=SEC_JOB_TIMEOUT)
                alert = record_job(name, None)
            except asyncio.TimeoutError:
                log.warning("Live job %s ran too long", name)
                alert = record_job(name, TimeoutError(f"{name} ran too long"))
                if not alert:
                    alert = f"⚠️ Background job `{name}` ran too long and was stopped. Everything else keeps running."
            except Exception as exc:
                log.exception("Live job %s failed", name)
                alert = record_job(name, exc)
            if alert:
                await self.job_alert(alert)
        for name, step in (("run_autograde", lambda: self.run_autograde(now.astimezone(timezone.utc))),
                           ("run_lock_grading", lambda: self.run_lock_grading(now.astimezone(timezone.utc))),
                           ("check_limits", lambda: self.check_limits(now))):
            try:
                await step()
                await self.job_alert(record_job(name, None))
            except Exception as exc:
                log.exception("%s failed", name)
                await self.job_alert(record_job(name, exc))
        try:
            await announce_milestones(self, now.astimezone(timezone.utc))
        except Exception:
            log.exception("Milestones failed")
        today = now.date().isoformat()
        rows = db().execute("SELECT guild_id, value FROM settings WHERE key = 'recap_channel'").fetchall()
        for row in rows:
            guild_id, channel = row["guild_id"], self.get_channel(int(row["value"]))
            if channel is None:
                continue
            try:
                if (now.weekday() == RECAP_DAY and now.hour >= RECAP_HOUR
                        and get_setting(guild_id, "last_recap") != today):
                    set_setting(guild_id, "last_recap", today)
                    await channel.send(embed=build_recap(guild_id))
                    if get_setting(guild_id, "show") != "off":
                        try:
                            await post_show(self, guild_id, channel, now.astimezone(timezone.utc))
                        except Exception:
                            log.exception("Sunday Show failed")
                    rivals_results(guild_id, pay=True)
                    roles_line = await assign_hot_roles(self, guild_id)
                    if roles_line:
                        await channel.send(roles_line, allowed_mentions=discord.AllowedMentions.none())
                last_month = (now.replace(day=1) - timedelta(days=1))
                month_key = last_month.strftime("%Y-%m")
                if (now.day == 1 and now.hour >= REMIND_HOUR
                        and get_setting(guild_id, "last_awards") != month_key):
                    set_setting(guild_id, "last_awards", month_key)
                    await channel.send(embed=build_awards(guild_id, last_month.year, last_month.month))
                    try:
                        dog = await assign_top_dog(self, guild_id, last_month.year, last_month.month)
                        if dog:
                            await channel.send(dog, allowed_mentions=discord.AllowedMentions.none())
                    except Exception:
                        log.exception("Top Dog failed")
                if now.hour >= REMIND_HOUR and get_setting(guild_id, "last_remind") != today:
                    set_setting(guild_id, "last_remind", today)
                    text = build_reminders(guild_id)
                    if text:
                        await channel.send(text, allowed_mentions=discord.AllowedMentions(
                            everyone=False, roles=False, users=True))
                await self.job_alert(record_job("daily_posts", None))
            except Exception as exc:
                log.exception("Daily posts failed for guild %s", guild_id)
                await self.job_alert(record_job("daily_posts", exc))

    # ---- messages ----------------------------------------------------------

    async def on_member_join(self, member):
        if not member.bot:
            try:
                dash_note_kick(member.id, False)
            except Exception:
                pass
        if member.bot or get_setting(member.guild.id, "welcome") != "on":
            return
        try:
            await member.send(WELCOME_TEXT)
        except Exception:
            pass

    async def on_member_remove(self, member):
        if member.bot:
            return
        try:
            dash_note_kick(member.id, True)
        except Exception:
            log.warning("Couldn't close the dashboard for a removed member")

    async def on_message(self, message: discord.Message):
        if message.author.bot:
            return
        if message.guild is not None:
            try:
                want = get_setting(message.guild.id, "ticket_channel") or ""
                cid = "".join(c for c in str(want) if c.isdigit())
                if cid and str(getattr(message.channel, "id", "")) == cid:
                    staff_ticket_add(message.guild.id, message)
                    return
            except Exception:
                log.exception("ticket ingest")
        if message.guild is None:
            dm_images = image_attachments(message)
            if dm_images:
                for pic in dm_images[:SLIP_MAX_PICS]:
                    await handle_dm_slip(self, message, pic)
            return
        if is_ask_channel(message.channel):
            await ask_channel_message(self, message)
            return
        images = image_attachments(message)
        mentioned = self.user is not None and self.mentions_me(message)
        intent = slip_intent(getattr(message, "content", "")) if images or mentioned else "log"
        if images and (self.is_receipts_channel(message.channel) or mentioned):
            if intent == "ask":
                pics = images[:SLIP_MAX_PICS]
                if len(pics) > 1:
                    await self.review_slips(message, message, pics)
                else:
                    await self.review_slip(message, message, pics[0])
            else:
                await self.log_slips(message, images)
            return
        if mentioned and not images and getattr(message, "reference", None):
            # "@PIMP-BOT log this" (or "@PIMP-BOT thoughts?") as a reply to someone's screenshot
            ref = message.reference.resolved
            if isinstance(ref, discord.Message) and not ref.author.bot and image_attachments(ref):
                ref_pics = image_attachments(ref)[:SLIP_MAX_PICS]
                if intent == "ask":
                    if len(ref_pics) > 1:
                        await self.review_slips(message, ref, ref_pics)
                    else:
                        await self.review_slip(message, ref, ref_pics[0])
                else:
                    await self.log_slips(ref, ref_pics)
                return
        if images and intent == "log" and get_setting(message.guild.id, "receipts_all") == "on":
            await self.log_slips(message, images, quiet=True)
            return
        if mentioned and not images:
            words = text_slip_words(message)
            route = text_route(words)
            if route == "status":
                await self.slip_status(message)
                return
            if route == "log" and await self.text_log(message, words):
                return
            if route == "review" and await self.text_review(message, words):
                return
        if self.user is not None and self.is_question(message):
            await self.handle_ask(message)

    def is_receipts_channel(self, channel) -> bool:
        """The channel itself, or a thread/forum post inside a receipts channel."""
        return (getattr(channel, "id", None) in self.receipt_channels
                or getattr(channel, "parent_id", None) in self.receipt_channels)

    def mentions_me(self, message: discord.Message) -> bool:
        return bool(re.search(rf"<@!?{self.user.id}>", getattr(message, "content", None) or "")
                    or self.bot_role_ids(message))

    async def log_slips(self, message: discord.Message, images: list, quiet: bool = False):
        for attachment in images[:SLIP_MAX_PICS]:
            try:
                await self.handle_slip(message, attachment, quiet=quiet)
            except Exception as exc:
                log.exception("Slip logging failed in #%s", getattr(message.channel, "name", "?"))
                SLIP_STATE["last_error"] = (now_iso(), f"{type(exc).__name__}: {exc}"[:300])
                if quiet:
                    continue
                try:
                    await message.reply(f"⚠️ I couldn't log that slip ({type(exc).__name__}). Use `/pick` for now, "
                                        "and an admin can run `/admin check` here to see what's wrong.",
                                        mention_author=False)
                except Exception:
                    log.exception("Couldn't even reply about the failed slip (check my permissions here)")

    def bot_role_ids(self, message: discord.Message) -> set[int]:
        return {r.id for r in (getattr(message, "role_mentions", None) or [])
                if r.is_bot_managed() and r.tags and r.tags.bot_id == self.user.id}

    def is_question(self, message: discord.Message) -> bool:
        """An explicit @mention of the bot (or its role), or a reply to one of its answers.
        Replies to pick cards don't count, so "nice hit" doesn't spend a question."""
        if re.search(rf"<@!?{self.user.id}>", message.content) or self.bot_role_ids(message):
            return True
        ref = message.reference.resolved if message.reference else None
        return (isinstance(ref, discord.Message) and ref.author.id == self.user.id
                and not ref.embeds and not ref.components and bool(ref.content))

    async def handle_ask(self, message: discord.Message):
        question = re.sub(rf"<@!?{self.user.id}>", "", message.content)
        for role_id in self.bot_role_ids(message):
            question = question.replace(f"<@&{role_id}>", "")
        question = question.strip()
        if not question:
            await message.reply(
                "Ask me about a player, team, matchup, or the weather, like "
                f"`@{self.user.display_name} how has donk played on LAN lately?`",
                mention_author=False)
            return
        if not ask_enabled():
            await message.reply("Questions aren't switched on yet: add a free `GROQ_API_KEY` (console.groq.com) or "
                                "`GEMINI_API_KEY` (or an `ANTHROPIC_API_KEY`) variable to the bot on Railway.", mention_author=False)
            return
        wait = self.ask_cooldowns.get(message.author.id, 0) + ASK_COOLDOWN_SECONDS - time.monotonic()
        if wait > 0:
            await message.reply(f"Give me {int(wait) + 1}s before the next question.",
                                mention_author=False)
            return
        count_key = f"asks:{datetime.now(TZ).date().isoformat()}"
        used = int(get_setting(message.guild.id, count_key) or 0)
        if used >= ASK_DAILY_LIMIT:
            await message.reply(f"That's the server's {ASK_DAILY_LIMIT} questions for today. "
                                "Back tomorrow.", mention_author=False)
            return
        self.ask_cooldowns[message.author.id] = time.monotonic()
        set_setting(message.guild.id, count_key, str(used + 1))

        user_text = f"Question from {message.author.display_name}: {question}"
        ref = message.reference.resolved if message.reference else None
        if isinstance(ref, discord.Message) and ref.author.id == self.user.id and ref.content:
            user_text = f"They're replying to your earlier answer:\n{ref.content[:1500]}\n\n" + user_text
        context = build_ask_context(message.guild.id, str(message.author.id), question)
        if context:
            user_text += "\n\nThe group's own data:\n" + context
        system = ASK_SYSTEM.format(bot_name=self.user.display_name,
                                   today=datetime.now(TZ).strftime("%A, %B %d, %Y"))
        system += (f"\n\nYour voice in this server: {persona_prompt(message.guild.id)}.\n"
                   "Talk like a person in this group chat, not a help desk. Two to eight sentences unless they asked "
                   "for a list. Address them by name. Be specific: name the player, the number, or the game. "
                   "Do not answer with a pep talk that could fit any question. "
                   "For questions about the group's own results (records, profit, hit rates, who's best at "
                   "something, someone's tendencies), use the group_stats tool and only quote its numbers. "
                   "If group numbers are already in the message, quote those and do not invent a record, a profit, "
                   "or a result. 'me', "
                   "'my' and 'I' mean the person asking. Ask for a chart when comparing several groups.")
        ctx = {"guild_id": message.guild.id, "asker_key": str(message.author.id), "chart": None}
        weather_pack = None
        answer, sources = None, []
        failed = False
        token = None
        try:
            async with message.channel.typing():
                if question_is_weather(question):
                    try:
                        weather_pack = await asyncio.wait_for(answer_weather(question), timeout=6)
                    except Exception:
                        log.warning("Weather lookup failed", exc_info=True)
                        weather_pack = None
                if weather_pack and weather_pack.get("brief"):
                    user_text += ("\n\nWeather already looked up. Quote these numbers. "
                                  "Do not invent a different temperature.\n" + weather_pack["brief"])
                token = ASK_DATA.set(ctx)
                try:
                    answer, sources = await asyncio.wait_for(
                        ask_any(system, user_text,
                                search=question_needs_search(question) and not weather_pack), timeout=10)
                finally:
                    if token is not None:
                        ASK_DATA.reset(token)
        except Exception:
            log.exception("Question failed")
            failed = True
        if failed and not weather_pack:
            await message.reply("I couldn't get an answer just now. Try again in a minute.",
                                mention_author=False)
            return
        if failed or not answer:
            if weather_pack:
                answer = weather_pack.get("brief") or "Here's the hourly forecast."
                sources = []
        if weather_pack and weather_pack.get("now") is not None:
            shown = int(round(float(weather_pack["now"])))
            brief = weather_pack.get("brief") or ""
            if brief and not re.search(rf"\b{shown}\b", answer or ""):
                answer = brief + "\n\n" + (answer or "")
        chart_file = None
        if ctx.get("chart"):
            try:
                png = await asyncio.to_thread(locked_render, render_bars, *ctx["chart"])
                chart_file = discord.File(png, filename="chart.png")
            except Exception:
                log.exception("Chart failed")
        weather_file = None
        if weather_pack:
            try:
                png = await asyncio.to_thread(locked_render, render_weather_card, weather_pack)
                weather_file = discord.File(png, filename="weather.png")
            except Exception:
                log.exception("Weather chart failed")
        if sources:
            answer += "\n\n-# Sources: " + " · ".join(f"<{u}>" for u in sources)
        reply_file = weather_file or chart_file
        for i, chunk in enumerate(split_message(answer or "I came up empty on that one.")):
            if i == 0:
                extra = {"file": reply_file} if reply_file else {}
                await message.reply(chunk, mention_author=False,
                                    allowed_mentions=discord.AllowedMentions.none(), **extra)
            else:
                await message.channel.send(chunk, allowed_mentions=discord.AllowedMentions.none())
        if weather_file and chart_file:
            await message.channel.send(file=chart_file, allowed_mentions=discord.AllowedMentions.none())

    async def handle_slip(self, message: discord.Message, attachment: discord.Attachment, quiet: bool = False):
        if quiet and not slip_reader_on():
            return
        until = cooling_until(message.guild.id, message.author.id)
        if until:
            if not quiet:
                await sec_private_notice(message, cooloff_message(until))
            return
        slip, reason = None, None
        wait = sec_wait(message.author.id, "slip_read", "slip") if slip_reader_on() else 0
        if wait:
            if not quiet:
                await message.reply(sec_slow_text(wait), mention_author=False)
            return
        if slip_reader_on() and (attachment.size or 0) <= MAX_IMAGE_BYTES:
            async with message.channel.typing():
                slip, reason = await read_slip_raced(attachment)
            await keep_slip_photo(attachment, message.id)
        elif slip_reader_on():
            reason = f"the image is too big ({(attachment.size or 0) // 1024} KB)"
            SLIP_STATE["last_error"] = (now_iso(), f"Image too big to read ({(attachment.size or 0) // 1024} KB)")

        tagged_slip = bool(filed_under(message)) and slip_tag_ready(slip)
        if quiet and not tagged_slip and not slip_result_ready(slip) and (slip is None or slip["cost"] is None or slip.get("_unsure")):
            return  # every-channel mode: memes and charts aren't slips, stay out of the way

        # A tag posts the slip under that member. A finished win or loss is filed even when the stake did not read.
        if tagged_slip or (slip is not None and (slip_result_ready(slip) or slip_settled_ready(slip))):
            slip = slip_file_amounts(slip)
            if tagged_slip:
                slip["placed"] = True
        elif slip is not None and slip.get("_unsure") and slip.get("legs"):
            await offer_extra_slips(message, slip)
            save_slip_draft(message.guild.id, message, slip)
            free_count("scan_confirm")
            note_slip_read("unsure", who=message.author.display_name,
                           title=str(slip.get("description") or "screenshot"), url=message.jump_url)
            await message.reply(free_unsure_note(slip), embed=slip_draft_embed(slip),
                                view=slip_draft_view(message.id, review=ai_enabled(), edit=True), mention_author=False)
            return

        # Couldn't read it (or reading is off): let the poster fill in a short form.
        if slip is None or slip["cost"] is None:
            note = "Got it. Tap below to log this slip."
            if slip_reader_on():
                free_count("fail")
                note_slip_read("fail", who=message.author.display_name,
                               title=reason or "couldn't read", url=message.jump_url)
                note = (f"I couldn't read that one: {reason}. Tap below to log it by hand." if reason else
                        "I couldn't read that one cleanly. Tap below to log it by hand.")
            await message.reply(note, view=log_slip_view(message.author.id),
                                mention_author=False)
            return

        bettor = await named_bettor(message)
        dup = find_duplicate(message.guild.id, bettor.id, slip) if slip.get("placed", True) else None
        if dup is not None:
            if quiet:
                return
            await offer_extra_slips(message, slip)
            save_slip_draft(message.guild.id, message, slip)
            await message.reply(f"👀 That looks like pick `#{dup['id']}` (logged "
                                f"<t:{int(datetime.fromisoformat(dup['created_at']).timestamp())}:R>), so I didn't log it "
                                "twice. If it's really a second entry, tap below.",
                                view=slip_draft_view(message.id, review=False), mention_author=False)
            return

        if not slip.get("placed", True):
            if quiet:
                return
            await offer_extra_slips(message, slip)
            save_slip_draft(message.guild.id, message, slip)
            sent = await message.reply("🤔 This one doesn't look placed yet (it's still on the entry screen), so I didn't "
                                       "log it. Want a breakdown, or is it in?", view=slip_draft_view(message.id),
                                       mention_author=False)
            add_ghost(message.guild.id, message.author.id, message.author.display_name, message.id, message.channel.id,
                      getattr(sent, "id", None), slip)
            return

        async def reply(**kw):
            return await message.reply(mention_author=False, **kw)
        await offer_extra_slips(message, slip)
        await self.log_parsed_slip(message.guild.id, message.author, message.channel, slip, message.jump_url, reply,
                                   bettor=bettor, shot_message_id=message.id,
                                   shot_attachment_id=getattr(attachment, "id", None))

    async def log_parsed_slip(self, guild_id: int, author, channel, slip: dict, slip_url: str, reply,
                              bettor=None, announce: bool = True, shot_message_id: Optional[int] = None,
                              shot_attachment_id: Optional[int] = None) -> int:
        """Log a slip Claude already read, post its card (with the live receipt), and do the extras."""
        owner = bettor or author
        legs = [str(leg).strip() for leg in (slip.get("legs") or []) if str(leg).strip()]
        payout = slip["payout"] if slip["payout"] is not None else 0.0
        pick_id = insert_pick(
            guild_id=guild_id,
            bettor_key=str(owner.id),
            bettor_name=owner.display_name,
            bettor_id=owner.id,
            logged_by=author.id,
            platform=str(slip.get("platform") or "Other")[:40],
            sport=(str(slip["sport"])[:60] if slip.get("sport") else None),
            description=str(slip.get("description") or "Slip")[:200],
            legs="\n".join(legs) or None,
            cost=slip["cost"],
            payout=payout,
            slip_url=slip_url,
        )
        apply_slip_meta(pick_id, slip)
        bind_slip_shot(pick_id, shot_message_id, shot_attachment_id, len(legs))
        mark_staff_test(guild_id, getattr(channel, "id", None), pick_id)
        if slip["status"] != "open":
            settle_pick(guild_id, pick_id, slip["status"], slip["returned"])

        p = get_pick(guild_id, pick_id)
        note = None
        if slip.get("_cost_blank"):
            note = f"I couldn't read the amount risked. Fix it with `/edit pick_id:{pick_id}`."
        if slip["payout"] is None:
            pay = f"I couldn't read the payout. Fix it with `/edit pick_id:{pick_id}`."
            note = f"{note} {pay}" if note else pay
        if getattr(owner, "id", None) != getattr(author, "id", None):
            filed = f"Filed under **{owner.display_name}**."
            note = f"{note}\n{filed}" if note else filed
        short = re.search(r"all (\d+) picks \(I found (\d+)\)", " ".join(str(u) for u in (slip.get("_unsure") or [])))
        if short and short.group(1) != short.group(2):
            gap = f"The header said {short.group(1)} picks and {short.group(2)} read."
            note = f"{note} {gap}" if note else gap
        view = settle_view(pick_id) if p["status"] == "open" else None
        SLIP_STATE["last_ok"] = now_iso()
        logged = voice_line(guild_id, "logged", name=call_name(guild_id, owner.id, owner.display_name))
        content = "\n".join(x for x in (logged, note) if x) or None
        embed, extra = pick_embed(p), {}
        sent = None
        posted_receipt = False
        if announce:
            try:
                async with channel.typing():
                    f = await receipt_file(self, p)
                embed.set_image(url=f"attachment://{f.filename}")
                extra["files"] = [f]
                posted_receipt = True
            except Exception:
                log.warning("Receipt image failed for pick %s", pick_id, exc_info=True)
            if view is not None:
                extra["view"] = view
            sent = await reply(content=content, embed=embed, **extra)
        if getattr(sent, "id", None):
            remember_pick_msg(guild_id, pick_id, channel.id, sent.id, receipt=posted_receipt)
        if announce:
            tip = headsup_text(guild_id, str(author.id), pick_id)
            if tip and not is_quiet(guild_id, author.id):
                try:
                    await author.send(tip)
                except Exception:
                    pass
            await voice_say(self, guild_id, f"{call_name(guild_id, author.id, author.display_name)} just logged {p['description']}, "
                                            f"{money(p['cost'])} to win {money(p['payout'])}.")
        note_slip_read("clean", pick_id, who=author.display_name, title=p["description"], url=slip_url)
        try:
            await announce_stacks(self, guild_id, pick_id, channel)
        except Exception:
            log.warning("Stack check failed", exc_info=True)
        return pick_id

    async def slip_status(self, message: discord.Message):
        """'@PIMP-BOT how's my slip doing?': live receipts for the asker's open slips."""
        async with message.channel.typing():
            files, total = await slip_status_files(self, message.guild.id, message.author.id)
        if not files:
            await message.reply("You've got no open slips from the last few days. Post a screenshot (or type one: "
                                "\"@PIMP-BOT log Tatum o22.5 PRA, $10 to win $30\") to log one.", mention_author=False)
            return
        more = f" (newest {len(files)} of {total}; `/open` lists the rest)" if total > len(files) else ""
        await message.reply(f"Here's where your open slip{'s stand' if len(files) > 1 else ' stands'} right now{more}:",
                            files=files, mention_author=False)

    async def text_log(self, message: discord.Message, words: str) -> bool:
        """'@PIMP-BOT log Tatum o22.5 PRA, Brown o20.5 pts, $10 to win $30': confirm card, nothing logged yet.
        False when it isn't a slip after all (the caller then treats it as a question)."""
        until = cooling_until(message.guild.id, message.author.id)
        if until:
            await sec_private_notice(message, cooloff_message(until))
            return True
        wait = sec_wait(message.author.id, "slip_read", "slip") if ai_enabled() else 0
        if wait:
            await message.reply(sec_slow_text(wait), mention_author=False)
            return True
        async with message.channel.typing():
            slip, reason = await read_text_slip(words)
        if slip is None:
            if reason == "not_slip" and not TEXT_LOG.search(words):
                return False
            await message.reply(f"I couldn't find a slip in that{': ' + reason if reason and reason != 'not_slip' else ''}. "
                                "Try one leg per line or comma, like "
                                "`@PIMP-BOT log Tatum over 22.5 PRA, Brown over 20.5 points, $10 to win $30`.",
                                mention_author=False)
            return True
        save_slip_draft(message.guild.id, message, slip, typed=True)
        dup = find_duplicate(message.guild.id, message.author.id, slip)
        await message.reply(content=(f"👀 Heads up: this matches pick `#{dup['id']}` you already logged." if dup else None),
                            embed=slip_draft_embed(slip), view=slip_draft_view(message.id, review=ai_enabled(), edit=True),
                            mention_author=False)
        return True

    async def text_review(self, message: discord.Message, words: str) -> bool:
        """'@PIMP-BOT thoughts on Tatum o22.5 PRA + Brown o20.5?': a breakdown with the X-ray, nothing logged.
        False when it isn't a slip after all (the caller then treats it as a question)."""
        if not ai_enabled():
            return False
        wait = sec_wait(message.author.id, "slip_read", "slip")
        if wait:
            await message.reply(sec_slow_text(wait), mention_author=False)
            return True
        async with message.channel.typing():
            slip, reason = await read_text_slip(words)
        if slip is None:
            return False
        gate = ask_gate(message.guild.id, message.author.id)
        if gate:
            await message.reply(gate, mention_author=False)
            return True
        slip["placed"] = False
        save_slip_draft(message.guild.id, message, slip, typed=True)
        async with message.channel.typing():
            text, xray = await slip_review(self, message.guild.id, message.author, slip, words)
        chunks = split_message(text)
        first = None
        for k, chunk in enumerate(chunks):
            extra = {}
            if k == 0 and xray is not None:
                extra["file"] = xray
            if k == len(chunks) - 1:
                extra["view"] = slip_draft_view(message.id, review=False, edit=True)
            if k == 0:
                first = await message.reply(chunk, mention_author=False, allowed_mentions=discord.AllowedMentions.none(),
                                            **extra)
            else:
                await message.channel.send(chunk, allowed_mentions=discord.AllowedMentions.none(), **extra)
        if find_duplicate(message.guild.id, message.author.id, dict(slip, cost=None)) is None:
            add_ghost(message.guild.id, message.author.id, message.author.display_name, message.id, message.channel.id,
                      getattr(first, "id", None), slip)
        await offer_data_picks(message, slip)
        return True

    async def review_slips(self, message: discord.Message, image_message: discord.Message, attachments: list):
        """Several photos are several slips. A tag posts each readable one, and the reply names every slip."""
        gate = ask_gate(message.guild.id, message.author.id)
        if gate:
            await message.reply(gate, mention_author=False)
            return
        pics = [a for a in attachments if (getattr(a, "size", 0) or 0) <= MAX_IMAGE_BYTES][:SLIP_MAX_PICS]
        if not pics:
            await message.reply("Those photos are too big to read. Send each slip on its own.", mention_author=False)
            return
        sem = asyncio.Semaphore(2)

        async def read_one(att):
            async with sem:
                try:
                    got = await read_slip_raced(att, budget=14)
                    await keep_slip_photo(att, image_message.id)
                    return got
                except Exception:
                    log.warning("One photo in a batch failed", exc_info=True)
                    return None, "that read failed"

        async with message.channel.typing():
            reads = await asyncio.gather(*(read_one(a) for a in pics))
        target = await named_bettor(message)
        tagged = getattr(target, "id", None) not in (None, getattr(message.author, "id", None))
        lines, posted, missed = [], 0, 0
        for i, (slip, reason) in enumerate(reads, 1):
            if not slip or not (slip.get("legs") or slip.get("description")):
                missed += 1
                why = f": {reason}" if reason else ""
                lines.append(f"**{i}.** I couldn't read that photo{why}.")
                continue
            blurb = slip_batch_blurb(i, slip)
            owner = target if tagged else message.author
            if slip_settled_ready(slip) or (tagged and slip_tag_ready(slip)):
                ready = slip_file_amounts(dict(slip))
                ready["placed"] = True
                try:
                    dup = find_duplicate(message.guild.id, owner.id, ready)
                    if dup is not None:
                        blurb += f"\nAlready on **{getattr(owner, 'display_name', 'them')}** as pick `#{dup['id']}`."
                    else:
                        async def _quiet(**kw):
                            return None
                        pid = await self.log_parsed_slip(
                            message.guild.id, message.author, message.channel, ready,
                            getattr(image_message, "jump_url", "") or "", _quiet, bettor=owner, announce=False,
                            shot_message_id=image_message.id,
                            shot_attachment_id=getattr(pics[i - 1], "id", None))
                        posted += 1
                        who_name = getattr(owner, "display_name", None) or "them"
                        blurb += f"\nPosted under **{who_name}** · pick `#{pid}`."
                        if ready.get("_cost_blank"):
                            blurb += f" The stake was blank. Fix it with `/edit pick_id:{pid}`."
                except Exception:
                    log.exception("Filing one slip from a batch failed")
                    blurb += "\nThat one did not post. Try it again on its own."
            elif tagged:
                blurb += "\nNot posted. The legs were not clear enough."
            lines.append(blurb)
        total = len(pics)
        if tagged and posted:
            intro = f"**{posted} of {total}** posted under **{target.display_name}**."
        elif posted:
            intro = f"**{posted} of {total}** logged."
        elif tagged:
            intro = f"**{total} photos.** None of them posted under **{target.display_name}**."
        else:
            intro = f"**{total} slips** in this message."
        if missed and not tagged:
            intro += f" {missed} did not read."
        text = intro + "\n\n" + "\n\n".join(lines)
        if not tagged and not posted:
            text += "\n\nTag a member on the photos to put them on a record."
        chunks = split_message(text)
        for k, chunk in enumerate(chunks):
            if k == 0:
                await message.reply(chunk, mention_author=False, allowed_mentions=discord.AllowedMentions.none())
            else:
                await message.channel.send(chunk, allowed_mentions=discord.AllowedMentions.none())

    async def review_slip(self, message: discord.Message, image_message: discord.Message, attachment):
        """A screenshot with a question gets a breakdown. Tagging a member posts the slip under their name."""
        gate = ask_gate(message.guild.id, message.author.id)
        if gate:
            await message.reply(gate, mention_author=False)
            return
        slip, reason = None, None
        question = re.sub(r"<@[!&]?\d+>", " ", getattr(message, "content", "") or "").strip()
        said = ""
        async with message.channel.typing():
            if (attachment.size or 0) <= MAX_IMAGE_BYTES:
                slip, reason = await read_slip_raced(attachment)
                await keep_slip_photo(attachment, image_message.id)
            if slip is None or not (slip.get("legs") or slip.get("description")):
                if ask_enabled():
                    try:
                        said = await asyncio.wait_for(glance_talk(
                            attachment, question, message.guild.id, message.author.display_name), timeout=8)
                    except Exception:
                        said = ""
        if slip is None or not (slip.get("legs") or slip.get("description")):
            if said:
                await message.reply(said, mention_author=False, allowed_mentions=discord.AllowedMentions.none())
                return
            free_count("fail")
            note_slip_read("fail", who=message.author.display_name,
                           title=reason or "couldn't read", url=getattr(image_message, "jump_url", "") or "")
            if reason and ("credit" in reason.lower() or "billing" in reason.lower()):
                await message.reply("I couldn't pull the legs off that screenshot. Type the names and I'll talk it through.",
                                    mention_author=False)
                return
            await message.reply(f"I couldn't read that slip{': ' + reason if reason else ''}. Try a clearer screenshot.",
                                mention_author=False)
            return
        if slip_settled_ready(slip):
            target = await named_bettor(message)
            owner = target or message.author
            ready = slip_file_amounts(dict(slip))
            ready["placed"] = True
            who = getattr(owner, "display_name", None) or "them"
            dup = find_duplicate(message.guild.id, getattr(owner, "id", 0), ready)
            if dup is not None:
                await message.reply(f"Already on **{who}** as pick `#{dup['id']}`.", mention_author=False)
                return
            async def reply(**kw):
                return await message.reply(mention_author=False, **kw)
            try:
                await self.log_parsed_slip(
                    message.guild.id, message.author, message.channel, ready,
                    getattr(image_message, "jump_url", "") or "", reply, bettor=owner,
                    shot_message_id=image_message.id, shot_attachment_id=getattr(attachment, "id", None))
            except Exception:
                log.exception("Logging a settled card failed")
            else:
                return
        save_slip_draft(message.guild.id, image_message, slip, mention_from=message)
        note_slip_read("unsure" if slip.get("_unsure") else "clean",
                       who=message.author.display_name,
                       title=str(slip.get("description") or "screenshot"),
                       url=getattr(image_message, "jump_url", "") or "")
        filed_note = ""
        target = await named_bettor(message)
        tagged = getattr(target, "id", None) not in (None, getattr(message.author, "id", None))
        if tagged and slip_tag_ready(slip):
            ready = slip_file_amounts(dict(slip))
            ready["placed"] = True
            dup = find_duplicate(message.guild.id, target.id, ready)
            if dup is not None:
                filed_note = f"Already on **{target.display_name}**'s record as pick `#{dup['id']}`."
            else:
                async def reply(**kw):
                    return await message.reply(mention_author=False, **kw)
                try:
                    pid = await self.log_parsed_slip(
                        message.guild.id, message.author, message.channel, ready,
                        getattr(image_message, "jump_url", "") or "", reply, bettor=target,
                        shot_message_id=image_message.id, shot_attachment_id=getattr(attachment, "id", None))
                    filed_note = f"Posted under **{target.display_name}** · pick `#{pid}`."
                    d = get_slip_draft(message.guild.id, image_message.id)
                    if d is not None:
                        d["used"] = pid
                        d["for_id"] = int(target.id)
                        d["for_name"] = target.display_name
                        set_setting(message.guild.id, f"draft:{image_message.id}", json.dumps(d))
                except Exception:
                    log.exception("Filing a slip under a mention failed")
        question = re.sub(r"<@[!&]?\d+>", " ", getattr(message, "content", "") or "").strip()
        async with message.channel.typing():
            text, xray = await slip_review(self, message.guild.id, message.author, slip, question)
        if slip.get("_unsure") and not filed_note:
            text = (f"⚠️ I wasn't sure about {', '.join(clip(u, 60) for u in slip['_unsure'][:3])} on this screenshot, "
                    "so double-check the legs below.\n\n" + text)
        if filed_note:
            text = text.replace("Not logged. Tap 🧾 to file it. Staff can put it under someone else.", filed_note)
        else:
            who = (get_slip_draft(message.guild.id, image_message.id) or {}).get("for_name")
            if who:
                text = text.replace("Not logged. Tap 🧾 to file it. Staff can put it under someone else.",
                                    f"Not logged. Tap 🧾 to file it under **{who}**.")
        logged = db().execute("SELECT id FROM picks WHERE guild_id = ? AND slip_url = ?",
                              (message.guild.id, image_message.jump_url)).fetchone()
        chunks = split_message(text)
        first = None
        for k, chunk in enumerate(chunks):
            extra = {}
            if k == 0 and xray is not None:
                extra["file"] = xray
            if k == len(chunks) - 1 and not logged:
                extra["view"] = slip_draft_view(image_message.id, review=False)
            if k == 0:
                first = await message.reply(chunk, mention_author=False, allowed_mentions=discord.AllowedMentions.none(),
                                            **extra)
            else:
                await message.channel.send(chunk, allowed_mentions=discord.AllowedMentions.none(), **extra)
        # their own slip, still on the entry screen: it becomes a ghost so we can tell them how the pass worked out
        if not logged and image_message.author.id == message.author.id and slip.get("placed") is False:
            add_ghost(message.guild.id, message.author.id, message.author.display_name, image_message.id,
                      message.channel.id, getattr(first, "id", None), slip)
        await offer_data_picks(message, slip)


bot = PicksBot()

PLATFORMS = [
    app_commands.Choice(name=n, value=n)
    for n in ("Kalshi", "PrizePicks", "Sportsbook", "Other")
]
OUTCOMES = [
    app_commands.Choice(name="Win", value="win"),
    app_commands.Choice(name="Loss", value="loss"),
    app_commands.Choice(name="Push", value="push"),
    app_commands.Choice(name="Void", value="void"),
    app_commands.Choice(name="Reopen (undo result)", value="open"),
]
LEG_RESULTS = [
    app_commands.Choice(name="Hit", value="hit"),
    app_commands.Choice(name="Miss", value="miss"),
    app_commands.Choice(name="Push", value="push"),
    app_commands.Choice(name="Not graded yet", value="open"),
]


def view_or_missing(p: sqlite3.Row):
    return settle_view(p["id"]) if p["status"] == "open" else settled_view(p["id"])


# ---- pick commands ----------------------------------------------------------

@bot.tree.command(name="pick", description="Log a pick")
@app_commands.guild_only()
@app_commands.describe(
    platform="Where the bet was placed",
    description="The play in one line, e.g. '3-leg NFL combo'",
    cost="Amount risked",
    payout="Total paid back if it wins (max payout)",
    legs="Optional: the legs, separated by semicolons",
    sport="Optional: NFL, CS2, NBA...",
    member="Optional: log it for another member (defaults to you)",
    label="Optional: log it under a name that isn't a Discord user",
    hidden="Optional: keep the details secret until it settles (proof you called it, no copycats)",
    confidence="Optional: how sure you are, 1 to 5 stars",
)
@app_commands.choices(platform=PLATFORMS)
async def pick_cmd(
    interaction: discord.Interaction,
    platform: app_commands.Choice[str],
    description: app_commands.Range[str, 1, 200],
    cost: app_commands.Range[float, 0],
    payout: app_commands.Range[float, 0],
    legs: Optional[app_commands.Range[str, 1, 900]] = None,
    sport: Optional[app_commands.Range[str, 1, 60]] = None,
    member: Optional[discord.Member] = None,
    label: Optional[app_commands.Range[str, 1, 60]] = None,
    hidden: Optional[bool] = None,
    confidence: Optional[app_commands.Range[int, 1, 5]] = None,
):
    until = cooling_until(interaction.guild_id, interaction.user.id)
    if until:
        await interaction.response.send_message(cooloff_message(until), ephemeral=True)
        return
    key, name, bettor_id = resolve_bettor(interaction, member, label)
    leg_text = None
    if legs:
        leg_text = "\n".join(part.strip() for part in legs.split(";") if part.strip()) or None
    pick_id = insert_pick(
        guild_id=interaction.guild_id, bettor_key=key, bettor_name=name,
        bettor_id=bettor_id, logged_by=interaction.user.id, platform=platform.value,
        sport=sport, description=description, legs=leg_text, cost=cost, payout=payout,
    )
    mark_staff_test(interaction.guild_id, interaction.channel_id, pick_id)
    if confidence:
        db().execute("UPDATE picks SET confidence = ? WHERE id = ?", (int(confidence), pick_id))
        db().commit()
    p = get_pick(interaction.guild_id, pick_id)
    if hidden:
        db().execute("UPDATE picks SET hidden = 1 WHERE id = ?", (pick_id,))
        db().commit()
        p = get_pick(interaction.guild_id, pick_id)
        await interaction.response.send_message(embed=private_card(p), view=settle_view(pick_id), ephemeral=True)
        await interaction.followup.send(
            f"🔒 **{name}** locked in a hidden {platform.value} pick (`#{pick_id}`) at "
            f"{datetime.now(TZ):%-I:%M %p}. It's revealed when it settles.")
        return
    await interaction.response.send_message(embed=pick_embed(p), view=settle_view(pick_id))
    try:
        msg = await interaction.original_response()
        remember_pick_msg(interaction.guild_id, pick_id, interaction.channel_id, msg.id)
    except Exception:
        pass
    try:
        await announce_stacks(interaction.client, interaction.guild_id, pick_id, interaction.channel)
    except Exception:
        log.warning("Stack check failed", exc_info=True)
    tip = headsup_text(interaction.guild_id, key, pick_id) if key == str(interaction.user.id) else None
    if tip:
        try:
            await interaction.followup.send(tip, ephemeral=True)
        except Exception:
            pass


@bot.tree.command(name="leg", description="Grade one leg of a parlay")
@app_commands.guild_only()
@app_commands.describe(pick_id="The pick number", leg="The leg number shown on the pick",
                       result="How that leg finished")
@app_commands.choices(result=LEG_RESULTS)
async def leg_cmd(interaction: discord.Interaction, pick_id: int, leg: int,
                  result: app_commands.Choice[str]):
    p = get_pick(interaction.guild_id, pick_id)
    if p is None:
        await interaction.response.send_message(f"No pick #{pick_id}.", ephemeral=True)
        return
    if not can_edit(interaction, p):
        await interaction.response.send_message(
            f"Only {p['bettor_name']} or a mod can grade this one.", ephemeral=True)
        return
    legs = get_legs(pick_id)
    if not legs:
        await interaction.response.send_message(
            f"Pick #{pick_id} has no legs listed. Add them with `/edit pick_id:{pick_id} legs:`.",
            ephemeral=True)
        return
    if not 1 <= leg <= len(legs):
        await interaction.response.send_message(
            f"Pick #{pick_id} has legs 1 to {len(legs)}.", ephemeral=True)
        return
    p, note = grade_leg(interaction.guild_id, pick_id, leg, result.value)
    await interaction.response.send_message(content=note or None, embed=pick_embed(p),
                                            view=view_or_missing(p))
    await audit(getattr(interaction, "client", None), interaction.guild_id, f"{who(interaction)} graded leg {leg} of {p['bettor_name']}'s "
                                                          f"pick #{pick_id}: {result.value}")


@bot.tree.command(name="grade", description="Look up results for a pick's open legs now")
@app_commands.guild_only()
@app_commands.describe(pick_id="The pick number")
@sec_rate("claude")
async def grade_cmd(interaction: discord.Interaction, pick_id: int):
    p = get_pick(interaction.guild_id, pick_id)
    if p is None:
        await interaction.response.send_message(f"No pick #{pick_id}.", ephemeral=True)
        return
    if not can_edit(interaction, p):
        await interaction.response.send_message(
            f"Only {p['bettor_name']} or a mod can grade this one.", ephemeral=True)
        return
    if p["status"] != "open":
        await interaction.response.send_message(f"Pick #{pick_id} is already settled.", ephemeral=True)
        return
    await interaction.response.defer(thinking=True, ephemeral=sec_secret(p))
    try:
        pick, lines, _, _ = await autograde(interaction.guild_id, pick_id)
    except Exception:
        log.exception("Grading pick %s failed", pick_id)
        await interaction.followup.send("I couldn't look that up just now. Try again in a minute.")
        return
    if not lines:
        await interaction.followup.send(
            f"Every leg on #{pick_id} is already graded. Settle it with `/result pick_id:{pick_id}`.")
        return
    msg = grading_message(pick, lines, final_try=False).replace(
        "Still open. I'll look again in 12 hours.", "Still open. Try `/grade` again once it's final."
        + ("" if ai_enabled() else " (Without an API key I can only look up moneylines, spreads and "
                                    "totals for major leagues.)"))
    await interaction.followup.send(split_message(msg)[0], embed=pick_embed(pick),
                                    view=view_or_missing(pick))


@bot.tree.command(name="last", description="Restate the last slip you logged, in this channel")
@app_commands.guild_only()
async def last_cmd(interaction: discord.Interaction):
    if interaction.guild is None:
        await interaction.response.send_message("That command needs a server.", ephemeral=True)
        return
    p = db().execute(
        "SELECT * FROM picks WHERE guild_id = ? AND bettor_key = ? ORDER BY id DESC LIMIT 1",
        (interaction.guild_id, str(interaction.user.id))).fetchone()
    if p is None:
        await interaction.response.send_message("You haven't logged a slip in this server yet.", ephemeral=True)
        return
    await interaction.response.send_message(embed=pick_embed(p))


@bot.tree.command(name="result", description="Settle a pick")
@app_commands.guild_only()
@app_commands.describe(
    pick_id="The pick number (shown as #12 on the pick)",
    outcome="How it finished",
    returned="Optional: exact amount paid back, for partial payouts or cash-outs",
)
@app_commands.choices(outcome=OUTCOMES)
async def result_cmd(
    interaction: discord.Interaction,
    pick_id: int,
    outcome: app_commands.Choice[str],
    returned: Optional[app_commands.Range[float, 0]] = None,
):
    p = get_pick(interaction.guild_id, pick_id)
    if p is None:
        await interaction.response.send_message(f"No pick #{pick_id}.", ephemeral=True)
        return
    if not can_edit(interaction, p):
        await interaction.response.send_message(
            f"Only {p['bettor_name']} or a mod can settle this one.", ephemeral=True)
        return
    before = p["status"]
    was_auto = (p["settled_by"] if "settled_by" in p.keys() else None) == "auto"
    p = settle_pick(interaction.guild_id, pick_id, outcome.value, returned)
    await interaction.response.send_message(embed=pick_embed(p), view=view_or_missing(p))
    if before not in ("open", outcome.value):
        line = (f"{who(interaction)} changed the grade on {p['bettor_name']}'s pick #{pick_id} "
                f"from {before} to {outcome.value}")
        if was_auto:
            line += ". Manual grade kept over the automatic one"
    else:
        line = (f"{who(interaction)} used /result on {p['bettor_name']}'s pick #{pick_id}: {outcome.value}")
    if returned is not None:
        line += f", returned {money(returned)}"
    await audit(getattr(interaction, "client", None), interaction.guild_id, line)


@bot.tree.command(name="open", description="Picks still waiting on a result")
@app_commands.guild_only()
@app_commands.describe(member="Optional: only this member's picks",
                       label="Optional: only picks under this name")
async def open_cmd(interaction: discord.Interaction,
                   member: Optional[discord.Member] = None,
                   label: Optional[str] = None):
    sql = "SELECT * FROM picks WHERE guild_id = ? AND status = 'open'"
    args: list = [interaction.guild_id]
    if member or label:
        key, _, _ = resolve_bettor(interaction, member, label)
        sql += " AND bettor_key = ?"
        args.append(key)
    rows = db().execute(sql + " ORDER BY id", args).fetchall()
    viewer = str(interaction.user.id)
    rows = [p for p in rows if not unrevealed_hidden(p) or str(p["bettor_key"]) == viewer]
    if not rows:
        await interaction.response.send_message("Nothing open right now.")
        return
    lines = [one_liner(p, viewer) for p in rows[:20]]
    if len(rows) > 20:
        lines.append(f"…and {len(rows) - 20} more")
    risk = sum(p["cost"] for p in rows)
    e = discord.Embed(title=f"Open picks ({len(rows)})", description=clip("\n".join(lines), 4000),
                      color=STATUS["open"][1])
    e.set_footer(text=f"{money(risk)} at risk")
    await interaction.response.send_message(embed=e)


@bot.tree.command(name="record", description="Someone's record, profit, ROI and leg hit rate")
@app_commands.guild_only()
@app_commands.describe(member="Optional: defaults to you",
                       label="Optional: a name that isn't a Discord user")
async def record_cmd(interaction: discord.Interaction,
                     member: Optional[discord.Member] = None,
                     label: Optional[str] = None):
    key, name, _ = resolve_bettor(interaction, member, label)
    stats = compute_stats(interaction.guild_id, key)
    if not stats:
        await interaction.response.send_message(f"No picks logged for {name} yet.")
        return
    s = stats[0]
    streak = current_streak(interaction.guild_id, key)
    e = discord.Embed(title=f"{s['name']} · {record_line(s)}" + (f" · {streak}" if streak else ""),
                      color=0x2ECC71 if s["net"] >= 0 else 0xE74C3C)
    e.add_field(name="Staked", value=money(s["staked"]))
    e.add_field(name="Returned", value=money(s["returned"]))
    e.add_field(name="Net", value=signed(s["net"]))
    e.add_field(name="ROI", value=f"{s['roi']:+.1f}%")
    e.add_field(name="Open", value=f"{s['open']} ({money(s['open_risk'])} at risk)")
    rate = hit_rate(leg_counts(interaction.guild_id, key))
    if rate:
        e.add_field(name="Legs", value=rate)
    season = current_season(interaction.guild_id)
    if season:
        mine = [x for x in season_stats(interaction.guild_id, season) if x["key"] == key]
        e.add_field(name=season["name"], value=f"{record_line(mine[0])} · {signed(mine[0]['net'])}" if mine
                    else "no settled picks yet")
    got = earned_badges(interaction.guild_id, key)
    if got:
        e.add_field(name=f"Badges {len(got)}/{len(BADGES)}", value=badge_line(got) + " · `/achievements`")
    gl = goal_line(interaction.guild_id, key) if key == str(interaction.user.id) else None   # goals are private
    if gl:
        e.add_field(name="🎯 Monthly goal", value=gl, inline=False)
    vis = "" if key == str(interaction.user.id) else " AND (hidden IS NULL OR hidden = 0 OR revealed_at IS NOT NULL)"
    recent = db().execute(
        f"""SELECT * FROM picks WHERE guild_id = ? AND bettor_key = ? AND status != 'open'{vis}
           ORDER BY settled_at DESC, id DESC LIMIT 5""",
        (interaction.guild_id, key)).fetchall()
    if recent:
        lines = [
            f"{STATUS[p['status']][0].split()[0]} `#{p['id']}` "
            f"{signed((p['returned'] or 0.0) - p['cost'])} · {clip(shown_desc(p) if key != str(interaction.user.id) else p['description'], 60)}"
            for p in recent
        ]
        e.add_field(name="Last 5 settled", value="\n".join(lines), inline=False)
    await interaction.response.send_message(embed=e)


LEADERBOARD_PERIODS = [app_commands.Choice(name=n, value=v) for n, v in
                       (("This season", "season"), ("Last 7 days", "week"), ("This month", "month"),
                        ("All time", "all"))]
RANK_BY = [app_commands.Choice(name="Profit ($)", value="net"), app_commands.Choice(name="Units", value="units"),
           app_commands.Choice(name="ROI", value="roi")]
PRESEASON_CHOICES = [app_commands.Choice(name="Count preseason picks", value="in"),
                     app_commands.Choice(name="Leave preseason out", value="out")]


@bot.tree.command(name="leaderboard", description="Everyone ranked by net profit (this season, if one's running)")
@app_commands.guild_only()
@app_commands.describe(period="Optional: season (default), last 7 days, this month or all time",
                       sport="Optional: one sport only",
                       preseason="Optional: count preseason picks or not (default: the server setting)",
                       rank_by="Optional: profit (default), units or ROI", platform="Optional: one platform")
@app_commands.choices(period=LEADERBOARD_PERIODS, sport=SPORT_CHOICES, preseason=PRESEASON_CHOICES, rank_by=RANK_BY,
                      platform=[app_commands.Choice(name=n, value=n) for n in ("Kalshi", "PrizePicks", "Sportsbook", "Other")])
async def leaderboard_cmd(interaction: discord.Interaction, period: Optional[app_commands.Choice[str]] = None,
                          sport: Optional[app_commands.Choice[str]] = None,
                          preseason: Optional[app_commands.Choice[str]] = None,
                          rank_by: Optional[app_commands.Choice[str]] = None,
                          platform: Optional[app_commands.Choice[str]] = None):
    gid = interaction.guild_id
    mode = period.value if period else "season"
    season = current_season(gid) if mode == "season" else None
    if mode == "season" and season is None:
        mode = "all"
    now = datetime.now(TZ)
    since = until = None
    if season:
        since, until, label = season["started_at"], season["ended_at"], season["name"]
    elif mode == "week":
        since, label = iso(now - timedelta(days=7)), "last 7 days"
    elif mode == "month":
        since, label = iso(now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)), now.strftime("%B")
    else:
        label = "all time"
    include_pre = (preseason.value == "in") if preseason else get_setting(gid, "exclude_preseason") != "on"
    sport_name = sport.value if sport else None
    plat = platform.value if platform else None
    stats = [s for s in compute_stats(gid, since=since, until=until, sport=sport_name, preseason=include_pre,
                                      platform=plat)
             if s["wins"] + s["losses"] + s["pushes"] > 0]
    by = rank_by.value if rank_by else "net"
    for s in stats:
        s["unit"] = unit_size_for(gid, s["key"])
        s["units"] = s["net"] / s["unit"] if s["unit"] else 0.0
    if by != "net":
        stats.sort(key=lambda s: s[by], reverse=True)
    moves = rank_movement(gid, [s["key"] for s in stats], since, until, sport=sport_name, preseason=include_pre,
                          platform=plat) if by == "net" else {}
    title = f"Leaderboard · {label}" + (f" · {sport_name}" if sport_name else "") + (f" · {plat}" if plat else "") \
        + {"units": " · by units", "roi": " · by ROI"}.get(by, "")
    if not stats:
        await interaction.response.send_message(
            f"No settled picks for {label}" + (f" in {sport_name}" if sport_name else "") + " yet."
            + (" Try `/leaderboard period:All time`." if mode != "all" else ""))
        return
    medals = ["🥇", "🥈", "🥉"]
    lines = []
    for i, s in enumerate(stats[:25]):
        rank = medals[i] if i < 3 else f"`{i + 1}.`"
        streak = current_streak(gid, s["key"]) if not sport_name else ""
        mv = moves.get(s["key"])
        arrow = f" ▲{mv}" if mv and mv > 0 else (f" ▼{-mv}" if mv and mv < 0 else "")
        value = f"{s['units']:+.1f}u" if by == "units" else signed(s["net"])
        lines.append(f"{rank} **{s['name']}**{arrow} · {record_line(s)} · "
                     f"{value} · ROI {s['roi']:+.1f}%" + (f" · {streak}" if streak else ""))
    e = discord.Embed(title=title, description="\n".join(lines), color=BRAND)
    inv_sql, inv_args = "SELECT * FROM picks WHERE guild_id = ? AND status IN ('win', 'loss')", [gid]
    if since:
        inv_sql += " AND settled_at >= ?"
        inv_args.append(since)
    if until:
        inv_sql += " AND settled_at < ?"
        inv_args.append(until)
    inv = [p for p in db().execute(inv_sql, inv_args).fetchall()
           if (not sport_name or sport_group(p["sport"]) == sport_name) and (include_pre or not p["preseason"])
           and (not plat or p["platform"] == plat)]
    inv_text = inverse_line(inv)
    if inv_text:
        e.add_field(name="If you'd faded everybody", value=inv_text, inline=False)
    e.set_footer(text="Settled picks only · record is W-L(-Push) · ▲▼ = places moved this week"
                      + (" · 1 unit = your /bankroll unit, or your average stake" if by == "units" else "")
                      + ("" if include_pre else " · preseason left out"))
    await interaction.response.send_message(embed=e)


@bot.tree.command(name="edit", description="Fix a pick's details")
@app_commands.guild_only()
@app_commands.describe(pick_id="The pick number", description="New one-line description",
                       cost="New amount risked", payout="New max payout",
                       legs="New legs, separated by semicolons (resets leg grades)",
                       person="Developer only: move this pick onto another person")
async def edit_cmd(
    interaction: discord.Interaction,
    pick_id: int,
    description: Optional[app_commands.Range[str, 1, 200]] = None,
    cost: Optional[app_commands.Range[float, 0]] = None,
    payout: Optional[app_commands.Range[float, 0]] = None,
    legs: Optional[app_commands.Range[str, 1, 900]] = None,
    person: Optional[discord.Member] = None,
):
    p = get_pick(interaction.guild_id, pick_id)
    if p is None:
        await interaction.response.send_message(f"No pick #{pick_id}.", ephemeral=True)
        return
    if not can_edit(interaction, p):
        await interaction.response.send_message(
            f"Only {p['bettor_name']}, a developer, or a mod can edit this one.", ephemeral=True)
        return
    updates: dict = {}
    if description is not None:
        updates["description"] = description
    if cost is not None:
        updates["cost"] = cost
    if payout is not None:
        updates["payout"] = payout
    if legs is not None:
        updates["legs"] = "\n".join(x.strip() for x in legs.split(";") if x.strip()) or None
    if person is not None and not crew_at_least(interaction.user.id, "developer", interaction.guild_id):
        await interaction.response.send_message(
            "Only a developer can move a pick onto someone else.", ephemeral=True)
        return
    if not updates and person is None:
        await interaction.response.send_message(
            "Nothing to change. Fill in at least one field.", ephemeral=True)
        return
    # If a settled pick was paid the standard amount, keep it in line with the
    # corrected numbers. A custom amount (partial payout, cash-out) is left alone.
    was_standard = (p["status"] != "open" and
                    p["returned"] == default_return(p["status"], p["cost"], p["payout"]))
    if updates:
        sets = ", ".join(f"{col} = ?" for col in updates)
        db().execute(f"UPDATE picks SET {sets} WHERE id = ?", (*updates.values(), pick_id))
    if person is not None:
        db().execute("UPDATE picks SET bettor_key = ?, bettor_name = ?, bettor_id = ? WHERE id = ?",
                     (str(person.id), person.display_name[:60], person.id, pick_id))
        updates["who"] = person.display_name
    db().commit()
    if "legs" in updates:
        set_legs_keep(pick_id, updates["legs"])
    p = get_pick(interaction.guild_id, pick_id)
    if was_standard and ("cost" in updates or "payout" in updates):
        p = settle_pick(interaction.guild_id, pick_id, p["status"])
    await interaction.response.send_message(embed=pick_embed(p), view=view_or_missing(p))
    await audit(getattr(interaction, "client", None), interaction.guild_id, f"{who(interaction)} edited pick #{pick_id} "
                                                          f"({p['bettor_name']}): {', '.join(updates)}")


@bot.tree.command(name="delete", description="Remove a pick")
@app_commands.guild_only()
@app_commands.describe(pick_id="The pick number")
async def delete_cmd(interaction: discord.Interaction, pick_id: int):
    p = get_pick(interaction.guild_id, pick_id)
    if p is None:
        await interaction.response.send_message(f"No pick #{pick_id}.", ephemeral=True)
        return
    if not can_edit(interaction, p):
        await interaction.response.send_message(
            f"Only {p['bettor_name']} or a mod can delete this one.", ephemeral=True)
        return
    db().execute("DELETE FROM legs WHERE pick_id = ?", (pick_id,))
    db().execute("DELETE FROM follows WHERE pick_id = ?", (pick_id,))
    db().execute("DELETE FROM picks WHERE id = ?", (pick_id,))
    db().commit()
    await interaction.response.send_message(
        f"Deleted pick #{pick_id} ({p['bettor_name']}: {clip(shown_desc(p), 80)}).")
    await audit(getattr(interaction, "client", None), interaction.guild_id, f"{who(interaction)} deleted pick #{pick_id} ({p['bettor_name']}: "
                                                          f"{clip(p['description'], 80)}, {money(p['cost'])}, {p['status']})")


EXPORT_FORMATS = [
    app_commands.Choice(name="Excel (Kalshi, PrizePicks and Summary tabs)", value="xlsx"),
    app_commands.Choice(name="CSV (one plain list)", value="csv"),
]


@bot.tree.command(name="export", description="Download every pick as a spreadsheet")
@app_commands.guild_only()
@app_commands.describe(format="Excel by default")
@app_commands.choices(format=EXPORT_FORMATS)
@sec_rate("file")
async def export_cmd(interaction: discord.Interaction,
                     format: Optional[app_commands.Choice[str]] = None):
    rows = db().execute(
        "SELECT * FROM picks WHERE guild_id = ? ORDER BY id", (interaction.guild_id,)
    ).fetchall()
    if not rows:
        await interaction.response.send_message("No picks to export yet.", ephemeral=True)
        return
    stamp = datetime.now(TZ).strftime("%Y-%m-%d")
    if format is None or format.value == "xlsx":
        data = build_workbook(interaction.guild_id)
        people = len({r["bettor_key"] for r in rows})
        await interaction.response.send_message(
            f"{len(rows)} picks from {people} {'person' if people == 1 else 'people'}.",
            file=discord.File(data, filename=f"picks_{stamp}.xlsx"))
        return
    buf = io.StringIO()
    writer = QaCsvWriter(buf)
    writer.writerow(["Pick #", "Logged (UTC)", "Bettor", "Platform", "Sport", "Description",
                     "Legs", "Legs Hit", "Cost", "Max Payout", "Status", "Returned", "Net",
                     "Settled (UTC)", "Slip", "Notes"])
    for p in rows:
        settled = p["status"] != "open"
        legs = [] if sec_secret(p) else get_legs(p["id"])
        legs_text = " | ".join(f"{leg['text']} [{leg['status']}]" for leg in legs)
        legs_hit = f"{sum(1 for leg in legs if leg['status'] == 'hit')}/{len(legs)}" if legs else ""
        writer.writerow([
            p["id"], p["created_at"], p["bettor_name"], p["platform"], p["sport"] or "",
            shown_desc(p), legs_text, legs_hit,
            f"{p['cost']:.2f}", f"{p['payout']:.2f}", p["status"],
            f"{p['returned']:.2f}" if settled else "",
            f"{(p['returned'] or 0.0) - p['cost']:.2f}" if settled else "",
            p["settled_at"] or "", p["slip_url"] or "", "" if sec_secret(p) else (p["notes"] or ""),
        ])
    data = io.BytesIO(buf.getvalue().encode("utf-8-sig"))  # BOM so Excel reads it right
    await interaction.response.send_message(
        f"{len(rows)} picks.", file=discord.File(data, filename=f"picks_{stamp}.csv"))


# ---- channel setup ----------------------------------------------------------

@bot.tree.command(name="receipts",
                  description="Auto-log slip screenshots: this channel, every channel, or off")
@app_commands.guild_only()
@app_commands.default_permissions(manage_guild=True)
@app_commands.choices(mode=[app_commands.Choice(name="On in this channel", value="on"),
                            app_commands.Choice(name="Off in this channel", value="off"),
                            app_commands.Choice(name="Every channel (quietly skips non-slips)", value="all"),
                            app_commands.Choice(name="Stop every-channel mode", value="all_off"),
                            app_commands.Choice(name="Show where it's on", value="show")])
@sec_staff_only
async def receipts_cmd(interaction: discord.Interaction, mode: Optional[app_commands.Choice[str]] = None):
    channel_id = interaction.channel_id
    m = mode.value if mode else None
    if m in ("all", "all_off"):
        set_setting(interaction.guild_id, "receipts_all", "on" if m == "all" else None)
        msg = ("📸 Every-channel mode is **on**: any screenshot that's a bet slip gets logged, anywhere in the server. "
               "Pictures that aren't slips are ignored quietly." if m == "all" else "Every-channel mode is **off**.")
        if m == "all" and not ai_enabled():
            msg += " ⚠️ It needs the Claude key (`ANTHROPIC_API_KEY` on Railway) to tell slips from other pictures."
        await interaction.response.send_message(msg)
        return
    if m == "show":
        rows = db().execute("SELECT channel_id FROM receipt_channels WHERE guild_id = ?", (interaction.guild_id,)).fetchall()
        where = ", ".join(f"<#{r['channel_id']}>" for r in rows) or "no channels"
        allm = get_setting(interaction.guild_id, "receipts_all") == "on"
        await interaction.response.send_message(
            f"Slip logging is on in: {where}." + (" Every-channel mode is **on** too." if allm else "") +
            "\nAnywhere else: @mention me with the screenshot (or reply to one with `@me log`).", ephemeral=True)
        return
    turn_off = channel_id in bot.receipt_channels if m is None else m == "off"
    if turn_off:
        db().execute("DELETE FROM receipt_channels WHERE channel_id = ?", (channel_id,))
        bot.receipt_channels.discard(channel_id)
        msg = "Slip logging is **off** for this channel."
    else:
        db().execute("INSERT OR REPLACE INTO receipt_channels (guild_id, channel_id) VALUES (?, ?)",
                     (interaction.guild_id, channel_id))
        bot.receipt_channels.add(channel_id)
        how = ("I'll read each screenshot and log it automatically."
               if ai_enabled() else
               "I'll reply to each screenshot with a button to log it.")
        msg = f"Slip logging is **on** for this channel. {how}"
        missing = missing_perms(getattr(interaction, "channel", None), getattr(getattr(interaction, "guild", None), "me", None))
        if missing:
            msg += f"\n⚠️ I'm missing **{', '.join(missing)}** here, so I can't reply. Fix my role or channel permissions."
    db().commit()
    await interaction.response.send_message(msg)


